[1463] = "Deckkraft des Vorschaufensters",
-- a625f9d4 English: Choose a whole number of upcoming recommendations, from zero (hidden) to five.
--     The preview shows the current priority results, not a full simulation of future cooldowns or
--     combat. Icons start at 64 pixels; resizing scales all icons while preserving their square
--     shape and the window ratio.
[1464] = "Eine ganze Zahl kommender Empfehlungen wählen, von null (ausgeblendet) bis fünf. Die Vorschau zeigt die aktuellen Prioritätsergebnisse, keine vollständige Simulation künftiger Abklingzeiten oder Kampfverläufe. Symbole beginnen bei 64 Pixeln; eine Größenänderung skaliert alle Symbole und behält ihre quadratische Form und das Seitenverhältnis des Fensters bei.",
-- 54b44fb7 English: Arrange preview icons horizontally (default) or vertically. Below the opacity
--     slider, Lock, Direction and Reset share one row.
[1465] = "Vorschausymbole horizontal (Standard) oder vertikal anordnen. Unter dem Deckkraft-Schieberegler teilen sich Sperren, Richtung und Zurücksetzen eine Zeile.",
-- 026621d4 English: Immediately return the preview window to the screen center and restore 64-pixel
--     icons without Apply. Other pending settings are preserved.
[1466] = "Das Vorschaufenster sofort in die Bildschirmmitte zurücksetzen und 64-Pixel-Symbole wiederherstellen, ohne Übernehmen. Andere ausstehende Einstellungen bleiben erhalten.",
-- 10d580ca English: Lock position and size
[1467] = "Position und Größe sperren",
