-- Context: Top-level tab of the settings window (next to General, Conditions, Functions ...):
--     integrations with other addons.
[1505] = "Integrationen",
-- 90c92d4c English: Lua editor
-- Context: Title of the Lua editor help window, and the name of a Lua editor settings row in the
--     profile comparison.
[1506] = "Lua-Editor",
-- d8cfde4d English: Choose optional addon integrations.
[1507] = "Optionale Addon-Integrationen wählen.",
-- 67af476d English: Automatic uses an available editor integration, with built-in syntax
--     highlighting as its fallback. Plain text disables highlighting. Apply changes the editor used
--     the next time you open a custom condition.
[1508] = "Automatisch verwendet eine verfügbare Editor-Integration und als Rückfall die integrierte Syntaxhervorhebung. Nur Text deaktiviert die Hervorhebung. Übernehmen ändert den Editor, der beim nächsten Öffnen einer benutzerdefinierten Bedingung verwendet wird.",
-- 9fe3f474 English: Loaded; editor integration not connected.
[1509] = "Geladen; Editor-Integration nicht verbunden.",
-- a79eae91 English: Not loaded.
[1510] = "Nicht geladen.",
-- 87b30347 English: These addons are optional. Only connected editor providers appear in the Editor
--     menu. Choosing an unavailable or failing editor falls back to the built-in editor.
[1511] = "Diese Addons sind optional. Nur verbundene Editor-Anbieter erscheinen im Menü Editor. Wird ein nicht verfügbarer oder fehlerhafter Editor gewählt, wird auf den integrierten Editor zurückgegriffen.",
-- f1fa67bf English: Choose the editor for custom Lua conditions. Built In syntax highlighting and
--     Plain text work without another addon. Automatic uses a registered optional provider when
--     available and falls back safely. Apply saves the choice; an open editor keeps its current
--     provider until reopened. LuaWorkbench and WowLua loading status is shown separately from
--     integration availability.
[1512] = "Den Editor für benutzerdefinierte Lua-Bedingungen wählen. Integrierte Syntaxhervorhebung und Nur Text funktionieren ohne weiteres Addon. Automatisch verwendet einen registrierten optionalen Anbieter, sofern verfügbar, und greift sonst sicher zurück. Übernehmen speichert die Wahl; ein geöffneter Editor behält seinen aktuellen Anbieter bis zum erneuten Öffnen. Der Ladestatus von LuaWorkbench und WowLua wird getrennt von der Verfügbarkeit der Integration angezeigt.",
-- dfab6835 English: Invalid condition: %s
-- %s #1: %s #1: why the custom condition is invalid, a short reason, e.g. "unexpected symbol near end"
[1513] = "Ungültige Bedingung: %s",
