-- 8eba81e3 English: Allowed types. A nested record or type list describes each item in a list.
[1527] = "Erlaubte Typen. Ein verschachtelter Datensatz oder eine Typliste beschreibt jedes Element einer Liste.",
-- 130a1408 English: Showing the first 200 fields. Use Advanced schema for larger definitions.
[1528] = "Es werden die ersten 200 Felder angezeigt. Für größere Definitionen das erweiterte Schema verwenden.",
