[1530] = "Tagfarbe",
-- 08b91fc6 English: Type a tag and press Enter, or choose an existing tag. Click a tag to remove
--     it; use the search results to change tag colors.
[1531] = "Einen Tag eingeben und die Eingabetaste drücken oder einen vorhandenen Tag wählen. Auf einen Tag klicken, um ihn zu entfernen; Tagfarben über die Suchergebnisse ändern.",
-- cbf6490e English: Search existing tags and select any number of them. Click a selected tag to
--     remove it; use the search results to change tag colors.
[1532] = "Vorhandene Tags durchsuchen und beliebig viele davon auswählen. Auf einen ausgewählten Tag klicken, um ihn zu entfernen; Tagfarben über die Suchergebnisse ändern.",
-- 45fa2eb3 English: Click to remove this tag. Use the search results to change tag colors.
[1533] = "Klicken, um diesen Tag zu entfernen. Tagfarben über die Suchergebnisse ändern.",
-- 84cfb5be English: Each callback keeps its own pending text while switching tabs. Undo and Redo
--     edit that callback buffer. Reset restores its last saved code, or the template for a new
--     condition, and can be undone. The main Apply saves and registers all callback buffers and
--     metadata; Discard drops the whole draft. Leaving with changes offers Apply, Discard or
--     Cancel. Check syntax runs no callbacks.
[1534] = "Jeder Callback behält beim Wechseln der Reiter seinen eigenen ausstehenden Text. Rückgängig und Wiederherstellen bearbeiten den Puffer dieses Callbacks. Zurücksetzen stellt seinen zuletzt gespeicherten Code oder bei einer neuen Bedingung die Vorlage wieder her und kann rückgängig gemacht werden. Das Haupt-Übernehmen speichert und registriert alle Callback-Puffer und Metadaten; Verwerfen verwirft den gesamten Entwurf. Beim Verlassen mit Änderungen werden Übernehmen, Verwerfen oder Abbrechen angeboten. Syntax prüfen führt keine Callbacks aus.",
-- 047aff36 English: No native Lua editor has been opened this session.
[1535] = "In dieser Sitzung wurde noch kein nativer Lua-Editor geöffnet.",
-- 5472dd28 English: Lua input diagnostics
-- Context: Title of the report window that shows Lua editor input diagnostics, for testers to copy.
[1536] = "Lua-Eingabediagnose",
-- 5c126363 English: Native input test
