--     moves the condition into another category (verb, imperative).
[1547] = "Verschieben",
-- 9e3bd238 English: Edit fields opens a graphical schema draft. Add, name, reorder or remove
--     fields, choose primitive or nested types, and edit nested fields. Apply stages the schema and
--     its field order. Advanced exposes the equivalent raw schema, parsed as data without executing
--     Lua.
[1548] = "Felder bearbeiten öffnet einen grafischen Schemaentwurf. Felder hinzufügen, benennen, umsortieren oder entfernen, primitive oder verschachtelte Typen wählen und verschachtelte Felder bearbeiten. Übernehmen merkt das Schema und seine Feldreihenfolge vor. Erweitert zeigt das gleichwertige Rohschema, das als Daten eingelesen wird, ohne Lua auszuführen.",
-- 5ed7c1f2 English: Decide whether this condition currently matches.
[1549] = "Entscheiden, ob diese Bedingung aktuell zutrifft.",
-- cbb89125 English: The stored values for this condition.
[1550] = "Die gespeicherten Werte dieser Bedingung.",
-- d02f326b English: Shared data for this evaluation cycle.
[1551] = "Gemeinsame Daten für diesen Auswertungszyklus.",
-- 5e32b652 English: Evaluation start time, in seconds from GetTime().
[1552] = "Startzeit der Auswertung in Sekunden laut GetTime().",
-- dbb95241 English: True matches; false or nil does not match.
[1553] = "true trifft zu; false oder nil trifft nicht zu.",
-- 33035e0c English: Check whether the stored condition values are complete and valid.
[1554] = "Prüfen, ob die gespeicherten Bedingungswerte vollständig und gültig sind.",
