[1555] = "Spezialisierungsbereich der Rotation.",
-- 0cb1ce78 English: True when the condition can be evaluated.
[1556] = "true, wenn die Bedingung ausgewertet werden kann.",
-- 18eb8e30 English: Describe the condition in readable words.
[1557] = "Die Bedingung in lesbaren Worten beschreiben.",
-- 4e9300c4 English: The human-readable condition summary.
[1558] = "Die lesbare Zusammenfassung der Bedingung.",
