[1559] = "Die Steuerelemente zum Bearbeiten dieser Bedingung erstellen.",
-- 2010cda9 English: The condition field container supplied by the UI adapter.
[1560] = "Der vom UI-Adapter bereitgestellte Container für die Bedingungsfelder.",
