[1566] = "Die Kennung der Bedingung.",
-- 46569f1f English: No return value is used.
[1567] = "Es wird kein Rückgabewert verwendet.",
-- 95a1b634 English: Release resources when the condition is removed or replaced.
[1568] = "Ressourcen freigeben, wenn die Bedingung entfernt oder ersetzt wird.",
-- 7f816072 English: Arguments
-- Context: Heading for a function's argument list: in the generated function documentation and in
--     the function source pane.
[1569] = "Argumente",
-- 16dcaa92 English: Returns
-- Context: Heading for a function's return values: in the generated function documentation and in
--     the function source pane.
[1570] = "Rückgabewerte",
-- b92993e1 English: Field names are Lua identifiers. Choose a field type from its dropdown. Records
--     contain named fields; allowed types contain alternatives, including nested records.
[1571] = "Feldnamen sind Lua-Bezeichner. Einen Feldtyp aus seinem Auswahlmenü wählen. Datensätze enthalten benannte Felder; erlaubte Typen enthalten Alternativen, einschließlich verschachtelter Datensätze.",
-- 5f81b556 English: A container carries its nested fields. Drop into a highlighted gap. Up / Down
--     moves within the current container; Duplicate copies the complete field; the red trash can
--     deletes it.
[1572] = "Ein Container nimmt seine verschachtelten Felder mit. In eine hervorgehobene Lücke ablegen. Hoch / Runter verschiebt innerhalb des aktuellen Containers; Duplizieren kopiert das vollständige Feld; der rote Mülleimer löscht es.",
-- d24ed6ad English: The chevron hides or shows nested fields. Add field appends to that container.
--     Undo / Redo affect the draft. Apply validates and stages the schema; Cancel leaves the
--     condition unchanged. Red borders mark invalid names or incomplete types.
[1573] = "Der Pfeil blendet verschachtelte Felder aus oder ein. Feld hinzufügen hängt an diesen Container an. Rückgängig / Wiederherstellen betreffen den Entwurf. Übernehmen prüft das Schema und merkt es vor; Abbrechen lässt die Bedingung unverändert. Rote Rahmen kennzeichnen ungültige Namen oder unvollständige Typen.",
-- 521fc51f English: Packaged helper from %s.
-- %s #1: %s #1: the file path of the packaged helper, e.g. "Functions/text.lua"
[1574] = "Mitgelieferte Hilfsfunktion aus %s.",
