[1583] = "Diese Funktion löschen? Bestehende abhängige Elemente werden nicht mehr verfügbar sein.",
-- 3ac00ae7 English: Deletion staged. Apply to remove this function.
[1584] = "Löschen vorgemerkt. Übernehmen, um diese Funktion zu entfernen.",
-- f2dc99c6 English: Function bindings
-- Context: Row label in the comparison of two custom functions: the function's list of bindings
--     (aliases to other helper functions).
[1585] = "Funktionsbindungen",
-- b19e02e9 English: Alias
[1586] = "Alias",
-- e64bbf11 English: This alias is already in use.
[1587] = "Dieser Alias wird bereits verwendet.",
-- c8037103 English: Function
-- Context: Word before the name in the function bundle review list: marks the entry as a function
--     (the alternative is Condition); followed by ": name".
[1588] = "Funktion",
-- a94fd0ee English: Add binding
[1589] = "Bindung hinzufügen",
-- 327c4c8c English: Packaged source is read-only. Duplicate it to create an editable custom
--     function.
[1590] = "Mitgelieferter Quellcode ist schreibgeschützt. Duplizieren, um eine bearbeitbare benutzerdefinierte Funktion zu erstellen.",
-- 8299c5ac English: Arguments become Lua parameters. Bindings expose selected helpers under
--     explicit local aliases. Editing an alias does not rewrite your Lua body.
[1591] = "Argumente werden zu Lua-Parametern. Bindungen stellen ausgewählte Hilfsfunktionen unter ausdrücklichen lokalen Aliasen bereit. Das Bearbeiten eines Alias schreibt den Lua-Code nicht um.",
-- 47b843fc English: New function
[1592] = "Neue Funktion",
-- edb574e3 English: Describe what this function does.
[1593] = "Beschreiben, was diese Funktion tut.",
-- 0d646ec9 English: Add a function or duplicate a packaged helper to edit its source.
[1594] = "Eine Funktion hinzufügen oder eine mitgelieferte Hilfsfunktion duplizieren, um ihren Quellcode zu bearbeiten.",
-- aebc00b0 English: LuaWorkbench supplies editing, completion, API knowledge and debugging. Debug
--     runs this buffer explicitly using the test arguments. It does not replace the saved rotation
--     or live callback.
[1595] = "LuaWorkbench bietet Bearbeitung, Vervollständigung, API-Wissen und Debugging. Debuggen führt diesen Puffer ausdrücklich mit den Testargumenten aus. Die gespeicherte Rotation oder der aktive Callback wird dadurch nicht ersetzt.",
-- ac6ddfe4 English: Connected: embedded editing, completion, API knowledge and debugging.
[1596] = "Verbunden: eingebettete Bearbeitung, Vervollständigung, API-Wissen und Debugging.",
-- e3b56b53 English: Review the dependency bundle before applying it.
[1597] = "Das Abhängigkeitspaket vor dem Übernehmen prüfen.",
-- e0ad4daf English: Function bindings (%d)
-- %d #1: %d #1: the number of function bindings, e.g. 3
[1598] = "Funktionsbindungen (%d)",
-- 1f10215d English: Aliases are local names in your Lua body. Changing an alias does not rewrite
--     the body.
[1599] = "Aliase sind lokale Namen im Lua-Code. Das Ändern eines Alias schreibt den Code nicht um.",
-- f81e71de English: Reuse existing
-- Context: Conflict action in the function bundle import: keep the function already present and
--     discard the imported one (dropdown entry).
[1600] = "Vorhandene wiederverwenden",
-- c72a3c56 English: Replace existing
-- Context: Conflict action in the function bundle import: overwrite the function already present
--     with the imported one (dropdown entry).
[1601] = "Vorhandene ersetzen",
-- 548fcd9a English: Import with new identifier
[1602] = "Mit neuer Kennung importieren",
-- 4759498a English: Create
-- Context: Conflict action in the function bundle import: add the imported entry as a new item
--     (dropdown entry).
[1603] = "Erstellen",
-- 41d342bd English: Review source
-- Context: Subtitle and heading of the dialog that shows the source code of a bundle entry so it
--     can be inspected before the import is applied.
[1604] = "Quellcode prüfen",
-- 195aae02 English: Original identifier
-- Context: Label in the function bundle review: the identifier the entry has in the bundle, shown
--     as "<label>: <id>".
[1605] = "Ursprüngliche Kennung",
-- 8bec02bf English: Destination identifier
-- Context: Label and edit-box title in the function bundle review: the identifier the entry will
--     get after import.
[1606] = "Zielkennung",
-- 32e8d276 English: Callback
-- Context: Label of the dropdown in the function-source review dialog that selects which callback
--     (a part of the code) to view.
[1607] = "Callback",
-- 222b67d3 English: Include custom function dependencies
[1608] = "Abhängigkeiten von benutzerdefinierten Funktionen einschließen",
-- df750ab9 English: Review import
-- Context: Button in the function bundle import dialog: checks the pasted bundle and lists what
--     would change, without applying it.
[1609] = "Import prüfen",
-- 454d876b English: Apply import
-- Context: Button in the function bundle review dialog: carries out the import (verb).
[1610] = "Import übernehmen",
-- b7143073 English: Function dependency bundle
-- Context: Title of the dialog for exporting/importing a bundle of functions together with the
--     functions they depend on.
[1611] = "Abhängigkeitspaket der Funktion",
-- 44fc47f3 English: Review the complete bundle before applying an import. Imported Lua can execute
--     when registered; only apply code you trust.
[1612] = "Vor dem Übernehmen eines Imports das vollständige Paket prüfen. Importiertes Lua kann bei der Registrierung ausgeführt werden; nur vertrauenswürdigen Code übernehmen.",
-- b5ca2246 English: Review each original name, destination and dependency below. Apply import saves
--     the complete reviewed bundle.
[1613] = "Unten jeden ursprünglichen Namen, jedes Ziel und jede Abhängigkeit prüfen. Import übernehmen speichert das vollständige geprüfte Paket.",
-- 0f2dd42f English: Conflict action
-- Context: Label of the dropdown in the function bundle review that chooses what to do when an
--     identifier already exists (Reuse, Replace, ...).
[1614] = "Aktion bei Konflikt",
-- 4e81098c English: Imported name
-- Context: Label of the edit box in the function bundle review holding the display name the
--     imported entry will have.
[1615] = "Importierter Name",
-- 8e818b1f English: Existing dependents
-- Context: Label in the function bundle review, followed by a list: the existing functions or
--     conditions that already use the one being replaced.
[1616] = "Bestehende abhängige Elemente",
-- 75c417a1 English: This imported definition is disabled. Its dependents remain unavailable.
[1617] = "Diese importierte Definition ist deaktiviert. Ihre abhängigen Elemente bleiben nicht verfügbar.",
-- 2643e762 English: Required functions
-- Context: Heading in the function bundle review for the functions the import depends on.
[1618] = "Benötigte Funktionen",
-- 103c8bbb English: Paste a bundle above, then review its original names, destinations and required
--     functions.
[1619] = "Oben ein Paket einfügen und dann seine ursprünglichen Namen, Ziele und benötigten Funktionen prüfen.",
-- 7f12e5bc English: Filter Built In or Custom helpers and search their names, identifiers or
--     descriptions. Packaged helpers show read-only source and typed documentation. Duplicate
--     creates an editable copy with a new stable identifier. Argument and return rows document the
--     Lua signature.
[1620] = "Integrierte oder benutzerdefinierte Hilfsfunktionen filtern und ihre Namen, Kennungen oder Beschreibungen durchsuchen. Mitgelieferte Hilfsfunktionen zeigen schreibgeschützten Quellcode und typisierte Dokumentation. Duplizieren erstellt eine bearbeitbare Kopie mit einer neuen stabilen Kennung. Argument- und Rückgabezeilen dokumentieren die Lua-Signatur.",
-- 812ccde3 English: Expand Function bindings to add explicit helper aliases and choose their
--     targets. Changing an alias does not rewrite your Lua body. Missing, disabled or invalid
--     dependencies keep their dependents unavailable until repaired.
[1621] = "Funktionsbindungen aufklappen, um ausdrückliche Aliase für Hilfsfunktionen hinzuzufügen und ihre Ziele zu wählen. Das Ändern eines Alias schreibt den Lua-Code nicht um. Fehlende, deaktivierte oder ungültige Abhängigkeiten lassen ihre abhängigen Elemente bis zur Reparatur nicht verfügbar.",
-- 9d60841e English: Check
[1622] = "Prüfen",
-- b64ac05f English: Live
-- Context: Checkbox in the condition test dialog: keeps re-running the test repeatedly while the
--     dialog stays open (live updating).
[1623] = "Live",
-- 324b134f English: Preview
-- Context: Title of a help topic: the preview of an effect in the effect editor, and the preview
--     window's sample in General settings help. A noun.
[1624] = "Vorschau",
-- a31ec5d7 English: The preview failed. Use /rm errors for details.
[1625] = "Die Vorschau ist fehlgeschlagen. Details mit /rm errors anzeigen.",
-- 1c103e84 English: Test values were not saved because they are not bounded plain data.
[1626] = "Die Testwerte wurden nicht gespeichert, da sie keine begrenzten, einfachen Daten sind.",
-- c1ab4306 English: Condition check
[1627] = "Bedingungsprüfung",
-- 0fa00491 English: Fields UI preview
-- Context: Title of the condition test dialog when it is opened from the developer debug tools to
--     preview a condition's fields user interface.
[1628] = "Vorschau der Feld-UI",
-- 367bba74 English: Help preview
-- Context: Title of the condition test dialog when it is opened from the developer debug tools to
--     preview a condition's help page.
[1629] = "Hilfevorschau",
-- 59e490f3 English: Edit detached test values below. Check validates them before evaluating. Live
--     is opt-in; test values are saved separately from the condition source.
[1630] = "Unten losgelöste Testwerte bearbeiten. Prüfen validiert sie vor der Auswertung. Live muss ausdrücklich eingeschaltet werden; Testwerte werden getrennt vom Quellcode der Bedingung gespeichert.",
-- 8b1c0e1c English: Preview runs only this callback with detached sample values. It does not save
--     or register the condition.
[1631] = "Die Vorschau führt nur diesen Callback mit losgelösten Beispielwerten aus. Die Bedingung wird dabei weder gespeichert noch registriert.",
-- 75d9602c English: Complete the source fields before checking.
[1632] = "Vor dem Prüfen die Quellfelder vervollständigen.",
-- 00454de7 English: Check could not compile the current source. Fix the source before checking
--     again.
[1633] = "Prüfen konnte den aktuellen Quellcode nicht kompilieren. Den Quellcode korrigieren und erneut prüfen.",
-- 6a255986 English: Skipped: invalid test values
[1634] = "Übersprungen: ungültige Testwerte",
-- 4607aa3d English: Validation: %s
-- %s #1: %s #1: the validation result, one of "Passed", "Failed" or "Unavailable" (translated), e.g. "Passed"
[1635] = "Validierung: %s",
-- 436fe71b English: Passed
-- Context: Result word in the condition test dialog: the test passed.
[1636] = "Bestanden",
-- 4c852a7e English: Evaluation: %s
-- %s #1: %s #1: the result of the test evaluation, a short phrase such as "True", "False" or "Skipped: invalid test values" (translated), e.g. "True"
[1637] = "Auswertung: %s",
-- 55a7b6a1 English: Fields UI and Help offer an explicit Preview of the current callback. Preview
--     uses detached sample values and the normal field or help renderer. It does not save,
--     register, validate or evaluate the condition. Closing it releases its controls and returns to
--     the source draft. Check syntax never runs a callback.
[1638] = "Feld-UI und Hilfe bieten eine ausdrückliche Vorschau des aktuellen Callbacks. Die Vorschau verwendet losgelöste Beispielwerte und die normale Feld- bzw. Hilfedarstellung. Sie speichert, registriert, validiert oder wertet die Bedingung nicht aus. Beim Schließen werden ihre Steuerelemente freigegeben, und es geht zurück zum Quellentwurf. Syntax prüfen führt niemals einen Callback aus.",
-- 106d8f1b English: Evaluate and Validate offer Check with the same Fields UI and detached sample
--     values. Check runs validation first, then evaluates only valid values. Results show true,
--     false or an unavailable reason. Live is opt-in and checks at most twice per second while this
--     panel is shown; closing stops it. Test values are saved separately and never enter condition
--     exports or rotation edits. Source changes run no callbacks unless you check again or enable
--     Live.
[1639] = "Auswerten und Validieren bieten Prüfen mit derselben Feld-UI und losgelösten Beispielwerten. Prüfen validiert zuerst und wertet dann nur gültige Werte aus. Die Ergebnisse zeigen true, false oder einen Grund für die Nichtverfügbarkeit. Live muss ausdrücklich eingeschaltet werden und prüft höchstens zweimal pro Sekunde, solange dieses Feld angezeigt wird; Schließen beendet es. Testwerte werden getrennt gespeichert und gelangen nie in Bedingungsexporte oder Rotationsbearbeitungen. Änderungen am Quellcode führen keine Callbacks aus, außer bei erneutem Prüfen oder aktiviertem Live.",
-- 5d331ffe English: Functions reference
-- Context: Title of a section in the custom condition editor's help: the page that documents public
--     helper functions (noun phrase).
[1640] = "Funktionsreferenz",
-- 64334745 English: The Functions page documents public helpers and their typed arguments, return
--     values and source. Context completion and hover use that reference; Ctrl-click a known helper
--     to open its source. Use explicit binding aliases for reusable custom helpers.
[1641] = "Die Seite Funktionen dokumentiert öffentliche Hilfsfunktionen mit ihren typisierten Argumenten, Rückgabewerten und ihrem Quellcode. Kontextvervollständigung und Mauszeiger-Tipps nutzen diese Referenz; Strg-Klick auf eine bekannte Hilfsfunktion öffnet ihren Quellcode. Für wiederverwendbare benutzerdefinierte Hilfsfunktionen ausdrückliche Bindungsaliase verwenden.",
-- 8f344bfe English: The imported definition type does not match this editor.
[1642] = "Der importierte Definitionstyp passt nicht zu diesem Editor.",
-- 91fe2974 English: Test values changed. Check again to refresh the result.
[1643] = "Die Testwerte haben sich geändert. Erneut prüfen, um das Ergebnis zu aktualisieren.",
-- 4087dcf1 English: Complete the highlighted test inputs before checking.
[1644] = "Vor dem Prüfen die hervorgehobenen Testeingaben vervollständigen.",
-- 532eaabd English: Test
-- Context: Button in the custom condition editor, and the dialog subtitle: runs the condition once
--     with sample input (verb).
[1645] = "Test",
-- e031e0df English: Run test
-- Context: Button and tooltip in the Lua workbench query panel: runs the entered code once with the
--     test arguments (verb phrase).
[1646] = "Test ausführen",
-- 312acdf1 English: Test condition
-- Context: Title of the dialog that tries a custom condition with sample values (verb phrase used
--     as a title).
[1647] = "Bedingung testen",
-- 34fb96f5 English: Debugger output
[1648] = "Debugger-Ausgabe",
-- e376955f English: Set test values in Test before debugging Evaluate.
[1649] = "Vor dem Debuggen von Auswerten Testwerte unter Test festlegen.",
-- 427ea36c English: Debugger output uses a detached sample and the normal field or help container.
[1650] = "Die Debugger-Ausgabe verwendet ein losgelöstes Beispiel und den normalen Feld- bzw. Hilfecontainer.",
-- af624aba English: Choose test values in Fields UI, then Run test to validate and evaluate. Help
--     is shown below the fields. Opening Test does not evaluate defaults. Live is opt-in.
[1651] = "Testwerte in der Feld-UI wählen und dann mit Test ausführen validieren und auswerten. Die Hilfe wird unter den Feldern angezeigt. Das Öffnen von Test wertet keine Standardwerte aus. Live muss ausdrücklich eingeschaltet werden.",
-- fba588f1 English: Test opens one condition-level dialog from any callback tab. It renders Fields
--     UI and Help together with detached values. Choose the fields and Run test to validate, then
--     evaluate only valid values. Opening the dialog does not evaluate defaults. Live is opt-in and
--     stops when the dialog closes. Committed test values are available to the debugger and stay
--     separate from source, exports and rotation edits. Check syntax never runs a callback.
[1652] = "Test öffnet aus jedem Callback-Reiter einen Dialog auf Bedingungsebene. Er stellt Feld-UI und Hilfe gemeinsam mit losgelösten Werten dar. Die Felder wählen und mit Test ausführen validieren; danach werden nur gültige Werte ausgewertet. Das Öffnen des Dialogs wertet keine Standardwerte aus. Live muss ausdrücklich eingeschaltet werden und endet beim Schließen des Dialogs. Festgelegte Testwerte stehen dem Debugger zur Verfügung und bleiben von Quellcode, Exporten und Rotationsbearbeitungen getrennt. Syntax prüfen führt niemals einen Callback aus.",
-- deba1c35 English: Nullable
-- Context: Checkbox in the argument/return type editor of the function source pane: the value may
--     also be nil (empty).
[1653] = "Nullbar",
-- fbf338e4 English: Add return value
[1654] = "Rückgabewert hinzufügen",
-- c75ed23e English: Lua returns multiple values in order. Each row documents one result.
[1655] = "Lua gibt mehrere Werte in fester Reihenfolge zurück. Jede Zeile dokumentiert ein Ergebnis.",
-- f968686c English: Expand code editor
-- Context: Tooltip of the button on the code editor corner in the function source pane: enlarges
--     the editor to fill the pane (verb phrase).
[1656] = "Code-Editor vergrößern",
-- cc81db61 English: Restore code editor
-- Context: Tooltip of the same button after the editor is enlarged: shrinks it back to its normal
--     size (verb phrase).
[1657] = "Code-Editor wiederherstellen",
-- cb050073 English: Choose a source helper and the local name used to call it in this Lua body.
--     Renaming the local name does not rewrite code. Source modules distinguish helpers with the
--     same name.
[1658] = "Eine Quell-Hilfsfunktion und den lokalen Namen wählen, unter dem sie in diesem Lua-Code aufgerufen wird. Das Umbenennen des lokalen Namens schreibt den Code nicht um. Quellmodule unterscheiden gleichnamige Hilfsfunktionen.",
-- cfaec007 English: Local name in code
[1659] = "Lokaler Name im Code",
-- d076565e English: Source helper
-- Context: Column caption in the function bindings table: the existing function the alias points
--     to.
[1660] = "Quell-Hilfsfunktion",
-- b49f05b5 English: Function names use letters, numbers and underscores, beginning with a letter or
--     underscore. Names suggest the local binding used to call them; registry identifiers stay
--     stable.
[1661] = "Funktionsnamen bestehen aus Buchstaben, Ziffern und Unterstrichen und beginnen mit einem Buchstaben oder Unterstrich. Die Namen geben die lokale Bindung vor, über die sie aufgerufen werden; Registrierungskennungen bleiben stabil.",
-- b545dd16 English: This cannot be undone.
[1662] = "Dies kann nicht rückgängig gemacht werden.",
-- f07f87d9 English: Delete this announcement?
[1663] = "Diese Ankündigung löschen?",
-- da985348 English: Type: %s
-- %s #1: %s #1: the Lua type name of the symbol, e.g. "number" or "string"
[1664] = "Typ: %s",
-- 78a0b485 English: Supported unit-token to localized unit-name lookup. Use value.unit as a key;
--     for example addon.units[value.unit]. Available tokens vary by client.
[1665] = "Unterstützte Zuordnung von Einheitenkennungen zu lokalisierten Einheitennamen. value.unit als Schlüssel verwenden, zum Beispiel addon.units[value.unit]. Die verfügbaren Kennungen hängen vom Client ab.",
-- b2a921f3 English: Supported unit-token to localized possessive unit-name lookup, such as your
--     target.
[1666] = "Unterstützte Zuordnung von Einheitenkennungen zu lokalisierten Einheitennamen im Genitiv, etwa „Ihr Ziel“.",
-- 7e1dc663 English: Rotation Master client compatibility adapter. Its methods return ordinary
--     readable results or nil with a reason when an observation is unavailable. Use a colon call,
--     or pass addon.Platform explicitly as self with a dot reference.
[1667] = "Kompatibilitätsadapter von Rotation Master für den Client. Seine Methoden liefern normale lesbare Ergebnisse oder nil mit einem Grund, wenn eine Beobachtung nicht verfügbar ist. Einen Aufruf mit Doppelpunkt verwenden oder bei einem Punktverweis addon.Platform ausdrücklich als self übergeben.",
-- bbc0cdbf English: Rotation Master spell catalog for resolving client-specific spell IDs, ranks,
--     names, icons and links.
[1668] = "Zauberkatalog von Rotation Master zum Auflösen clientspezifischer Zauber-IDs, Ränge, Namen, Symbole und Links.",
-- 18123a69 English: Utility functions explicitly bound to this condition or function. Choose a
--     completion to bind an available custom function before inserting its reference.
[1669] = "Hilfsfunktionen, die ausdrücklich an diese Bedingung oder Funktion gebunden sind. Eine Vervollständigung wählen, um eine verfügbare benutzerdefinierte Funktion zu binden, bevor ihr Verweis eingefügt wird.",
-- 16356339 English: Rotation Master custom function
[1670] = "Benutzerdefinierte Funktion von Rotation Master",
-- 902c5c44 English: Rotation Master built-in function
[1671] = "Integrierte Funktion von Rotation Master",
-- 0443c4a6 English: Rotation Master value
-- Context: Heading in the Lua editor's hover text for a symbol that is a plain value provided by
--     Rotation Master (not a function); the alternatives are 'Rotation Master custom function' and
--     'Rotation Master built-in function'.
[1672] = "Wert von Rotation Master",
-- 1a845fe0 English: Global function (documentation unavailable on this client)
[1673] = "Globale Funktion (Dokumentation auf diesem Client nicht verfügbar)",
-- 6912e131 English: This client does not provide signature documentation for this function. No
--     arguments or return types have been inferred.
[1674] = "Dieser Client stellt keine Signaturdokumentation für diese Funktion bereit. Es wurden keine Argumente oder Rückgabetypen abgeleitet.",
-- 90092e5f English: Invoke
[1675] = "Aufruf",
-- cb214676 English: Functions are shared across profiles after Apply. Call custom utilities as
--     functions.name(...); accepting completion adds the dependency binding. Typed calls need a
--     binding under Function bindings. Built In examples show dot or colon explicitly.
[1676] = "Funktionen werden nach dem Übernehmen profilübergreifend geteilt. Benutzerdefinierte Hilfsfunktionen als functions.name(...) aufrufen; das Annehmen einer Vervollständigung fügt die Abhängigkeitsbindung hinzu. Typisierte Aufrufe benötigen eine Bindung unter Funktionsbindungen. Integrierte Beispiele zeigen Punkt oder Doppelpunkt ausdrücklich.",
-- d03262ba English: Show line numbers
-- Context: Checkbox in Integrations settings (Lua editor section): shows line numbers in the Lua
--     code editors; also a help topic title.
[1677] = "Zeilennummern anzeigen",
-- f12fff00 English: Line-number visibility applies to every condition and function code editor.
[1678] = "Die Sichtbarkeit der Zeilennummern gilt für jeden Code-Editor für Bedingungen und Funktionen.",
-- 596578e6 English: Call a saved custom utility as functions.name(...). Accepting a completion
--     attaches its stable dependency binding; for a typed call, choose its helper under Function
--     bindings. Existing direct aliases still work. The Invoke example shows required addon dot or
--     colon syntax for Built In functions. Renaming an alias does not rewrite source. Missing,
--     disabled or invalid dependencies keep consumers unavailable.
[1679] = "Eine gespeicherte benutzerdefinierte Hilfsfunktion als functions.name(...) aufrufen. Das Annehmen einer Vervollständigung hängt ihre stabile Abhängigkeitsbindung an; für einen typisierten Aufruf ihre Hilfsfunktion unter Funktionsbindungen wählen. Bestehende direkte Aliase funktionieren weiterhin. Das Beispiel unter Aufruf zeigt die für integrierte Funktionen erforderliche addon-Syntax mit Punkt oder Doppelpunkt. Das Umbenennen eines Alias schreibt den Quellcode nicht um. Fehlende, deaktivierte oder ungültige Abhängigkeiten lassen die Nutzer nicht verfügbar.",
-- 38416c88 English: Choose the editor for custom Lua conditions and functions. Show line numbers
--     applies across code editors. Built In syntax highlighting and Plain text work without another
--     addon. Automatic selects a connected provider or falls back safely. Apply saves settings;
--     editor changes take effect on reopening, and line-number visibility updates open editors.
--     LuaWorkbench and WowLua loading status is shown separately from integration availability.
[1680] = "Den Editor für benutzerdefinierte Lua-Bedingungen und -Funktionen wählen. Zeilennummern anzeigen gilt für alle Code-Editoren. Integrierte Syntaxhervorhebung und Nur Text funktionieren ohne weiteres Addon. Automatisch wählt einen verbundenen Anbieter oder greift sicher zurück. Übernehmen speichert die Einstellungen; Editoränderungen wirken beim erneuten Öffnen, und die Sichtbarkeit der Zeilennummern wird in geöffneten Editoren aktualisiert. Der Ladestatus von LuaWorkbench und WowLua wird getrennt von der Verfügbarkeit der Integration angezeigt.",
-- 50c3cb6e English: All namespaces
-- Context: First entry of the namespace filter dropdown on the Functions page: show functions from
--     every namespace.
[1681] = "Alle Namensräume",
-- 5605815a English: Call a utility as namespace.name(...). Built In namespaces follow source files;
--     custom functions choose their Namespace. Accepting a completion attaches its stable
--     dependency binding; for a typed call, add its qualified name under Function bindings.
--     Namespaces do not supply self: the Invoke example includes a method receiver explicitly, and
--     Existing API preserves its original dot or colon spelling. Existing aliases still work.
--     Renaming a function or namespace does not rewrite existing code or bindings. Missing,
--     disabled or invalid dependencies keep consumers unavailable.
[1682] = "Eine Hilfsfunktion als namespace.name(...) aufrufen. Integrierte Namensräume folgen den Quelldateien; benutzerdefinierte Funktionen wählen ihren Namensraum selbst. Das Annehmen einer Vervollständigung hängt ihre stabile Abhängigkeitsbindung an; für einen typisierten Aufruf ihren qualifizierten Namen unter Funktionsbindungen hinzufügen. Namensräume liefern kein self: Das Beispiel unter Aufruf enthält einen Methodenempfänger ausdrücklich, und Bestehende API behält die ursprüngliche Schreibweise mit Punkt oder Doppelpunkt bei. Bestehende Aliase funktionieren weiterhin. Das Umbenennen einer Funktion oder eines Namensraums schreibt bestehenden Code und Bindungen nicht um. Fehlende, deaktivierte oder ungültige Abhängigkeiten lassen die Nutzer nicht verfügbar.",
-- 66506282 English: Choose a source helper and its name in this Lua body, such as custom.ready or
--     utils.getCached. Namespaces are private to this callback. Renaming a binding does not rewrite
--     code.
[1683] = "Eine Quell-Hilfsfunktion und ihren Namen in diesem Lua-Code wählen, etwa custom.ready oder utils.getCached. Namensräume sind privat für diesen Callback. Das Umbenennen einer Bindung schreibt den Code nicht um.",
-- 5226404c English: Existing API
[1684] = "Bestehende API",
-- e572edc2 English: Name in code
-- Context: Column caption in the function bindings table and tooltip of the alias field: the name a
--     binding is called inside the Lua code.
[1685] = "Name im Code",
-- c4e4e7ab English: Namespace
-- Context: Label of the namespace box in the function source pane and a help section title: the
--     dotted group name under which a function is listed.
[1686] = "Namensraum",
-- c6d86222 English: Namespaces group functions; they do not supply a receiver. Accept a completion
--     to bind the shown dotted call. For a typed call, add the same qualified name under Function
--     bindings. Method examples include the required receiver explicitly. Functions are shared
--     across profiles after Apply.
[1687] = "Namensräume gruppieren Funktionen; sie liefern keinen Empfänger. Eine Vervollständigung annehmen, um den angezeigten Aufruf mit Punkt zu binden. Für einen typisierten Aufruf denselben qualifizierten Namen unter Funktionsbindungen hinzufügen. Methodenbeispiele enthalten den erforderlichen Empfänger ausdrücklich. Funktionen werden nach dem Übernehmen profilübergreifend geteilt.",
-- 76209725 English: Private utility-function namespace. It contains only explicit bindings for this
--     callback.
[1688] = "Privater Namensraum für Hilfsfunktionen. Er enthält nur die ausdrücklichen Bindungen für diesen Callback.",
-- 481da3a7 English: Argument
-- Context: Row title and add-button text in the function source pane: one function argument (noun).
--     The same place has "Return".
[1689] = "Argument",
-- e0836fce English: Bindings (%d)
-- %d #1: %d #1: the number of function bindings, e.g. 3
[1690] = "Bindungen (%d)",
-- 6ecb5a70 English: Call a utility as namespace.name(...). Built In namespaces follow source files;
--     custom functions choose their Namespace. Accepting a completion attaches its stable
--     dependency binding; for a typed call, add its qualified name under Function bindings.
--     Namespaces do not supply self. Pass a method receiver explicitly in a namespaced dot call;
--     object:method(x) is Lua shorthand for object.method(object, x). Existing addon APIs remain
--     compatible with saved definitions. Existing aliases still work. Renaming a function or
--     namespace does not rewrite existing code or bindings. Missing, disabled or invalid
--     dependencies keep consumers unavailable.
[1691] = "Eine Hilfsfunktion als namespace.name(...) aufrufen. Integrierte Namensräume folgen den Quelldateien; benutzerdefinierte Funktionen wählen ihren Namensraum selbst. Das Annehmen einer Vervollständigung hängt ihre stabile Abhängigkeitsbindung an; für einen typisierten Aufruf ihren qualifizierten Namen unter Funktionsbindungen hinzufügen. Namensräume liefern kein self. Bei einem Punktaufruf über einen Namensraum den Methodenempfänger ausdrücklich übergeben; object:method(x) ist die Lua-Kurzform für object.method(object, x). Bestehende Addon-APIs bleiben mit gespeicherten Definitionen kompatibel. Bestehende Aliase funktionieren weiterhin. Das Umbenennen einer Funktion oder eines Namensraums schreibt bestehenden Code und Bindungen nicht um. Fehlende, deaktivierte oder ungültige Abhängigkeiten lassen die Nutzer nicht verfügbar.",
-- d35a9985 English: Changing argument or return order can break existing callers. Rotation Master
--     will not rewrite their Lua code. Continue?
[1692] = "Eine Änderung der Reihenfolge von Argumenten oder Rückgabewerten kann bestehende Aufrufer beschädigen. Rotation Master schreibt deren Lua-Code nicht um. Fortfahren?",
-- 2199cecc English: Click an Arguments or Returns heading to collapse or expand it. + Argument and
--     + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use
--     Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and
--     Nullable document accepted values; Description explains each input or result. Lua can return
--     several ordered results. Reordering a saved function warns because positional callers may
--     need changes; RM does not rewrite call sites.
[1693] = "Auf eine Überschrift Argumente oder Rückgabewerte klicken, um sie ein- oder auszuklappen. + Argument und + Rückgabewert hängen beim Klicken an oder fügen beim Ziehen an einer hervorgehobenen Lücke ein. Eine Zeile ziehen oder Hoch / Runter verwenden, um umzusortieren; Strg-Ziehen nimmt die folgenden Zeilen mit. Der Mülleimer entfernt eine Zeile. Typ und Nullbar dokumentieren die zulässigen Werte; Beschreibung erklärt jede Eingabe bzw. jedes Ergebnis. Lua kann mehrere geordnete Ergebnisse zurückgeben. Beim Umsortieren einer gespeicherten Funktion erscheint eine Warnung, da positionsabhängige Aufrufer eventuell angepasst werden müssen; RM schreibt Aufrufstellen nicht um.",
-- 6b0143d0 English: Return
-- Context: Row title and add-button text in the function source pane: one function return value
--     (noun). The same place has "Argument".
[1694] = "Rückgabewert",
-- 2584fdfb English: Changing argument order can break existing callers. Rotation Master will not
--     rewrite their Lua code. Continue?
[1695] = "Eine Änderung der Argumentreihenfolge kann bestehende Aufrufer beschädigen. Rotation Master schreibt deren Lua-Code nicht um. Fortfahren?",
-- 79fbb27b English: Changing return documentation order does not rewrite return statements or
--     existing callers. Review the Lua body and callers for the new order. Continue?
[1696] = "Eine Änderung der Reihenfolge in der Rückgabedokumentation schreibt weder return-Anweisungen noch bestehende Aufrufer um. Lua-Code und Aufrufer auf die neue Reihenfolge prüfen. Fortfahren?",
-- 2266dd0b English: Card controls
-- Context: Heading of a section in the argument editor help: explains the controls on an argument's
--     card.
[1697] = "Kartensteuerung",
-- 1f03f52f English: Describe this value for function documentation, completion and hover help.
--     Changes remain in the draft until Apply.
[1698] = "Beschreibt diesen Wert für Funktionsdokumentation, Vervollständigung und Hover-Hilfe. Änderungen bleiben bis „Übernehmen“ im Entwurf.",
-- 9513dcfb English: Drag a card to reorder arguments; Ctrl-drag includes following arguments. Up
--     and down move one position. Duplicate copies the argument with a unique name; the trash can
--     removes it. Reordering a saved function requires confirmation because existing callers are
--     not rewritten.
[1699] = "Karte ziehen, um Argumente neu anzuordnen; Strg-Ziehen nimmt die folgenden Argumente mit. „Nach oben“ und „Nach unten“ verschieben um eine Position. „Duplizieren“ kopiert das Argument mit einem eindeutigen Namen; der Papierkorb entfernt es. Das Umsortieren einer gespeicherten Funktion erfordert eine Bestätigung, da bestehende Aufrufer nicht umgeschrieben werden.",
-- 33f24b5d English: Drag a card to reorder return documentation; Ctrl-drag includes following
--     returns. Up and down move one position. Duplicate copies the documented return value; the
--     trash can removes it. Return order in this list does not rewrite return statements or
--     callers.
[1700] = "Karte ziehen, um die Dokumentation der Rückgabewerte neu anzuordnen; Strg-Ziehen nimmt die folgenden Rückgabewerte mit. „Nach oben“ und „Nach unten“ verschieben um eine Position. „Duplizieren“ kopiert den dokumentierten Rückgabewert; der Papierkorb entfernt ihn. Die Reihenfolge in dieser Liste ändert weder return-Anweisungen noch Aufrufer.",
-- 74057930 English: Rendered output appears here when the callback runs or steps through widget
--     creation.
[1701] = "Die gerenderte Ausgabe erscheint hier, wenn der Callback ausgeführt oder die Widget-Erstellung schrittweise durchlaufen wird.",
-- 47b50257 English: Set values in Test before running or debugging this condition.
[1702] = "Werte unter „Test“ festlegen, bevor diese Bedingung ausgeführt oder debuggt wird.",
-- 96aa8cc3 English: The argument name is the local parameter available in the Lua body. Use a valid
--     Lua identifier. Renaming this documentation does not rewrite references in the code.
[1703] = "Der Argumentname ist der lokale Parameter, der im Lua-Rumpf verfügbar ist. Einen gültigen Lua-Bezeichner verwenden. Das Umbenennen in dieser Dokumentation schreibt keine Verweise im Code um.",
-- 438e9a47 English: Type and Nullable describe the values accepted or returned by this function.
--     They document the contract; they do not rewrite or validate values in the Lua body.
[1704] = "„Typ“ und „Nullable“ beschreiben die Werte, die diese Funktion annimmt oder zurückgibt. Sie dokumentieren den Vertrag; Werte im Lua-Rumpf werden dadurch weder umgeschrieben noch geprüft.",
-- 42e8bcf1 English: Debuffs
-- Context: Condition category in the icon picker's category list: debuff-related icons (plural
--     noun).
[1705] = "Schwächungszauber",
-- e89b30aa English: Resources
