[1919] = "%d der Zauber, die Blizzard vorschlagen kann, liegen auf keiner Ihrer Aktionsleisten, daher überspringt die Karte sie.",
-- 29258402 English: %s, and %d more
-- Context: End of a spell list in a tooltip: %s is the first few spell names (comma-separated) not
--     on the action bars, %d is how many more are not shown, giving 'A, B, C, and 4 more'.
-- %s #1: %s #1: the names of the first missing spells, separated by commas, e.g. "Fireball, Frostbolt, Ice Lance"
-- %d #2: %d #2: how many more are not listed, e.g. 4
[1920] = "%s und %d weitere",
-- f657f763 English: Not on your action bars: %s.
-- %s #1: %s #1: the names of the spells that are not on the action bars, separated by commas, e.g. "Fireball, Frostbolt"
[1921] = "Nicht auf Ihren Aktionsleisten: %s.",
-- d60bbc94 English: Rotation Master highlights a step by lighting the action button that holds it.
--     No action bar button holds this action right now, so this step is skipped and the next step
--     is used instead. Put it on an action bar to use it. Spells inside macros count only where the
--     game lets addons read macros (not on Retail).
[1922] = "Rotation Master hebt einen Schritt hervor, indem es die Aktionstaste aufleuchten lässt, die ihn enthält. Derzeit enthält keine Taste einer Aktionsleiste diese Aktion, daher wird dieser Schritt übersprungen und stattdessen der nächste Schritt verwendet. Legen Sie sie auf eine Aktionsleiste, um sie zu verwenden. Zauber in Makros zählen nur dort, wo das Spiel Addons das Lesen von Makros erlaubt (nicht in Retail).",
-- 982f6c69 English: Rotation Master highlights a cooldown by lighting the action button that holds
--     it. No action bar button holds this action right now, so this cooldown is never shown or
--     announced. Put it on an action bar to use it. Spells inside macros count only where the game
--     lets addons read macros (not on Retail).
[1923] = "Rotation Master hebt eine Abklingzeit hervor, indem es die Aktionstaste aufleuchten lässt, die sie enthält. Derzeit enthält keine Taste einer Aktionsleiste diese Aktion, daher wird diese Abklingzeit nie angezeigt oder angekündigt. Legen Sie sie auf eine Aktionsleiste, um sie zu verwenden. Zauber in Makros zählen nur dort, wo das Spiel Addons das Lesen von Makros erlaubt (nicht in Retail).",
-- 9ec46751 English: Rotation Master highlights an action by lighting the button that holds it, so
--     it can't highlight these. The card still works for every suggestion that is on your bars: it
--     skips one only when it is suggested, and the next step is used instead. Put these on an
--     action bar to use them.
[1924] = "Rotation Master hebt eine Aktion hervor, indem es die Schaltfläche beleuchtet, die sie enthält, und kann diese daher nicht hervorheben. Die Karte funktioniert weiterhin für jeden Vorschlag, der auf Ihren Leisten liegt: Sie überspringt einen nur, wenn er vorgeschlagen wird, und es wird stattdessen der nächste Schritt verwendet. Legen Sie diese auf eine Aktionsleiste, um sie zu nutzen.",
-- c6fa3ead English: Skipped, not on your action bars (they cannot be highlighted): %s.
-- %s #1: %s #1: the skipped steps, separated by semicolons, each with its name and place, e.g. "Fireball (step 3); Frostbolt (cooldown)"
[1925] = "Übersprungen, nicht auf Ihren Aktionsleisten (sie können nicht hervorgehoben werden): %s.",
