[1983] = "des Leiters Ihrer Gruppe",
-- fad43537 English: Absolute health target (negative means deficit) or percentage fraction.
[1984] = "Absolutes Gesundheitsziel (negativ bedeutet Defizit) oder Prozentwert als Bruchteil.",
-- 29a55788 English: All original results, preserving nil positions and return count.
[1985] = "Alle ursprünglichen Ergebnisse, unter Beibehaltung der nil-Positionen und der Anzahl der Rückgabewerte.",
-- c7e69e75 English: Apply the legacy integer or canonical numeric-string spelling test. Numbers use
--     floor equality; strings must equal the spelling obtained after numeric conversion and floor.
--     Other types return false. This is not a finite-number validator.
[1986] = "Den alten Test auf Ganzzahl oder kanonische numerische Zeichenkettenschreibweise anwenden. Zahlen verwenden Gleichheit nach floor; Zeichenketten müssen der Schreibweise entsprechen, die sich nach numerischer Umwandlung und floor ergibt. Andere Typen ergeben false. Dies ist keine Prüfung auf endliche Zahlen.",
-- 69eb2e21 English: Arguments forwarded unchanged to the observed function.
[1987] = "Argumente, die unverändert an die beobachtete Funktion weitergereicht werden.",
-- 1d513028 English: Arguments forwarded unchanged; types, identity, arity and nil positions
--     distinguish cache entries.
[1988] = "Unverändert weitergereichte Argumente; Typen, Identität, Stelligkeit und nil-Positionen unterscheiden Cache-Einträge.",
-- 3e8d2702 English: Availability or query-validation reason for a nil level observation.
[1989] = "Verfügbarkeits- oder Abfragevalidierungsgrund für eine nil-Stufenbeobachtung.",
-- e2ffe9af English: Availability or query-validation reason for a nil level.
[1990] = "Verfügbarkeits- oder Abfragevalidierungsgrund für eine nil-Stufe.",
-- 66134514 English: Availability or query-validation reason when no current state can be read.
[1991] = "Verfügbarkeits- oder Abfragevalidierungsgrund, wenn kein aktueller Zustand gelesen werden kann.",
-- 77b92c6d English: Availability or query-validation reason when the whole observation is
--     unavailable.
[1992] = "Verfügbarkeits- oder Abfragevalidierungsgrund, wenn die gesamte Beobachtung nicht verfügbar ist.",
-- 11483c22 English: Availability or validation reason for a nil result.
[1993] = "Verfügbarkeits- oder Validierungsgrund für ein nil-Ergebnis.",
-- bd62d347 English: Availability or validation reason when the record is nil.
[1994] = "Verfügbarkeits- oder Validierungsgrund, wenn der Datensatz nil ist.",
-- cab01ca9 English: Availability or validation reason when the result is nil.
[1995] = "Verfügbarkeits- oder Validierungsgrund, wenn das Ergebnis nil ist.",
-- 37cddc45 English: Availability reason for a nil result.
[1996] = "Verfügbarkeitsgrund für ein nil-Ergebnis.",
-- eced4849 English: Availability reason when resolution fails; nil on success.
[1997] = "Verfügbarkeitsgrund, wenn die Auflösung fehlschlägt; nil bei Erfolg.",
-- 09403547 English: Cache an observation after it returns a non-nil value; retry observations whose
--     entire return tuple is nil. Uses the same exact argument keys as getCached.
[1998] = "Eine Beobachtung zwischenspeichern, sobald sie einen Wert ungleich nil zurückgibt; Beobachtungen, deren gesamtes Rückgabetupel nil ist, erneut versuchen. Verwendet dieselben exakten Argumentschlüssel wie getCached.",
-- ec80f70e English: Calculate a checked health-history rate using an explicit finite window and
--     clock. Preserve ordered weighting, per-row live canonical rounding, skipped streams, array
--     holes, fractional keys and final visited ages. A fixed 4096-unit budget covers visited rows
--     and accumulation bins across both streams; excess or invalid consumed arithmetic returns
--     unavailable, never a partial estimate or clamp. This new API has its own source identity;
--     historical trend functions remain unchanged.
[1999] = "Eine geprüfte Rate aus dem Gesundheitsverlauf mit explizitem endlichem Fenster und expliziter Uhr berechnen. Geordnete Gewichtung, kanonische Live-Rundung pro Zeile, übersprungene Datenströme, Array-Lücken, gebrochene Schlüssel und das zuletzt besuchte Alter bleiben erhalten. Ein festes Budget von 4096 Einheiten deckt besuchte Zeilen und Akkumulationsklassen beider Datenströme ab; überschüssige oder ungültige Arithmetik ergibt „nicht verfügbar“, nie eine Teilschätzung oder Begrenzung. Diese neue API hat eine eigene Quellidentität; historische Trendfunktionen bleiben unverändert.",
-- e3a904cc English: Call an observation once per cache and exact argument tuple, including nil
--     results. Pass the evaluation cache to share observations within a recommendation cycle; nil
--     cache calls directly.
[2000] = "Eine Beobachtung einmal pro Cache und exaktem Argumenttupel aufrufen, nil-Ergebnisse eingeschlossen. Den Auswertungs-Cache übergeben, um Beobachtungen innerhalb eines Empfehlungszyklus zu teilen; ohne Cache (nil) erfolgt der Aufruf direkt.",
-- cb8a709c English: Callback invoked after changing the selected unit.
[2001] = "Callback, der nach dem Ändern der ausgewählten Einheit aufgerufen wird.",
-- f4755bc2 English: Callback receiving the committed spell value.
[2002] = "Callback, der den festgelegten Zauberwert erhält.",
-- 8473e032 English: Caller-owned evaluation observation cache; nil queries afresh.
[2003] = "Vom Aufrufer verwalteter Beobachtungs-Cache der Auswertung; nil fragt neu ab.",
-- d07ec966 English: Capability or clock observation availability reason.
[2004] = "Verfügbarkeitsgrund aus Client-Unterstützung oder Uhrbeobachtung.",
-- aca2f51b English: Capability or observation availability reason for a nil class.
[2005] = "Verfügbarkeitsgrund aus Client-Unterstützung oder Beobachtung für eine nil-Klasse.",
-- fb8dd5ac English: Check whether a spell can be recommended now, allowing a spell whose remaining
--     cooldown ends with the current global cooldown. On Retail and Forever, where cooldown times
--     are secret in combat, readiness comes from the never-secret isEnabled, isActive and isOnGCD
--     flags instead. This checks cooldown readiness only; it does not check learned status, range
--     or resource usability. Pass evaluation time from evalStart or GetTime().
[2006] = "Prüft, ob ein Zauber jetzt empfohlen werden kann, wobei ein Zauber zugelassen wird, dessen verbleibende Abklingzeit mit der aktuellen globalen Abklingzeit endet. In Retail und Forever, wo Abklingzeiten im Kampf geheim sind, ergibt sich die Bereitschaft stattdessen aus den nie geheimen Flags isEnabled, isActive und isOnGCD. Geprüft wird nur die Bereitschaft der Abklingzeit, nicht der Lernstatus, die Reichweite oder ob genug Ressourcen vorhanden sind. Übergeben Sie die Auswertungszeit aus evalStart oder GetTime().",
-- 1081f5fc English: Check whether a table has a non-nil value at a key. A stored false value still
--     counts as present; this does not scan table values.
[2007] = "Prüfen, ob eine Tabelle unter einem Schlüssel einen Wert ungleich nil hat. Ein gespeichertes false gilt weiterhin als vorhanden; Tabellenwerte werden nicht durchsucht.",
-- 3f1a5911 English: Checkbox widget with boolean value and callback methods.
[2008] = "Kontrollkästchen-Widget mit booleschem Wert und Callback-Methoden.",
-- 8373609b English: Choose the supplied player value only for the literal player unit token; every
--     other unit selects the nonplayer value. Selected false and nil values are preserved.
[2009] = "Den übergebenen Spielerwert nur für die literale Einheitenkennung player wählen; jede andere Einheit wählt den Nicht-Spieler-Wert. Ausgewählte Werte false und nil bleiben erhalten.",
-- 68e9defe English: Classification, validation or availability reason for a nil result.
[2010] = "Klassifizierungs-, Validierungs- oder Verfügbarkeitsgrund für ein nil-Ergebnis.",
-- 7fc7159a English: Classify a numeric item as a glyph for the requested class, using guarded
--     native item metadata. Class is optional and defaults to the readable player class. This
--     establishes item classification only, not equipped status or an item-to-glyph-spell ID
--     mapping.
[2011] = "Einen numerischen Gegenstand anhand abgesicherter nativer Gegenstandsmetadaten als Glyphe für die angefragte Klasse klassifizieren. Die Klasse ist optional und standardmäßig die lesbare Spielerklasse. Dies stellt nur die Gegenstandsklassifizierung fest, weder den Status „angelegt“ noch eine Zuordnung von Gegenstand zu Glyphen-Zauber-ID.",
-- 355b4c25 English: Client-family, query-validation or required-observation availability reason for
--     a nil result.
[2012] = "Verfügbarkeitsgrund aus Client-Familie, Abfragevalidierung oder erforderlicher Beobachtung für ein nil-Ergebnis.",
-- 56d0a810 English: Client-policy, capability, call or observation availability reason for a nil
--     form.
[2013] = "Verfügbarkeitsgrund aus Client-Richtlinie, Client-Unterstützung, Aufruf oder Beobachtung für eine nil-Gestalt.",
-- fffddfca English: Client-policy, capability, call or observation availability reason for a nil
--     record.
[2014] = "Verfügbarkeitsgrund aus Client-Richtlinie, Client-Unterstützung, Aufruf oder Beobachtung für einen nil-Datensatz.",
-- 7a0f627b English: Client-policy, native-call or required membership availability reason for a nil
--     record.
[2015] = "Verfügbarkeitsgrund aus Client-Richtlinie, nativem Aufruf oder erforderlicher Zugehörigkeit für einen nil-Datensatz.",
-- 0a8d99a6 English: Closed kind: runner, resist or immune.
[2016] = "Geschlossene Art: runner, resist oder immune.",
-- 6999f76c English: Closed scalar kind: current or maximum.
[2017] = "Geschlossene Skalarart: current oder maximum.",
-- a7224c57 English: Collect table keys and sort them by their associated values using Lua less-than
--     comparison. This sorts values rather than key names; equal values have no guaranteed key
--     order.
[2018] = "Tabellenschlüssel sammeln und mit dem Lua-Kleiner-als-Vergleich nach ihren zugehörigen Werten sortieren. Sortiert werden die Werte, nicht die Schlüsselnamen; bei gleichen Werten ist die Schlüsselreihenfolge nicht garantiert.",
-- 508c105b English: Combat-policy, capability, observation or scan-budget reason for a nil count.
[2019] = "Grund aus Kampfrichtlinie, Client-Unterstützung, Beobachtung oder Scan-Budget für eine nil-Anzahl.",
-- 14b9d8a2 English: Combined signed weighted rate from the original formula; malformed or nonfinite
--     inputs retain the legacy error/numeric behavior.
[2020] = "Kombinierte vorzeichenbehaftete gewichtete Rate aus der ursprünglichen Formel; fehlerhafte oder nicht endliche Eingaben behalten das alte Fehler- bzw. Zahlenverhalten.",
-- ee842735 English: Compare the selected unit creature ID with one existing saved creature-type
--     key. Resolve the fixed key-to-ID identity in one private executable mapper; gameplay matching
--     does not depend on the mutable localized UI caption map. Share complete native observations
--     within the supplied evaluation-pass cache by actual observer, receiver and unit, including
--     absence and unavailable reasons. Known absence or a known different ID returns false; an
--     unavailable required observation returns nil with a reason. No longterm state or caption
--     mutation is added.
[2021] = "Die Kreatur-ID der ausgewählten Einheit mit einem vorhandenen gespeicherten Kreaturtyp-Schlüssel vergleichen. Die feste Zuordnung von Schlüssel zu ID wird in einem privaten ausführbaren Mapper aufgelöst; der Spielabgleich hängt nicht von der veränderlichen lokalisierten Beschriftungstabelle der Oberfläche ab. Vollständige native Beobachtungen werden im übergebenen Cache des Auswertungsdurchlaufs nach tatsächlichem Beobachter, Empfänger und Einheit geteilt, einschließlich Abwesenheit und Gründen für Nichtverfügbarkeit. Bekannte Abwesenheit oder eine bekannt abweichende ID ergibt false; eine nicht verfügbare erforderliche Beobachtung ergibt nil mit einem Grund. Es wird kein Langzeitzustand und keine Änderung der Beschriftungen hinzugefügt.",
-- 098e89f6 English: Compare two exact unit tokens using UnitIsUnit after checking only the first
--     token with UnitExists. A readable absent first unit returns false without comparing. Required
--     missing, failed, restricted or malformed observations return nil with a reason. No second
--     existence query, GUID lookup or inferred identity is added.
[2022] = "Zwei exakte Einheitenkennungen mit UnitIsUnit vergleichen, nachdem nur die erste Kennung mit UnitExists geprüft wurde. Eine lesbar abwesende erste Einheit ergibt false ohne Vergleich. Erforderliche fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Beobachtungen ergeben nil mit einem Grund. Es wird keine zweite Existenzabfrage, keine GUID-Suche und keine abgeleitete Identität hinzugefügt.",
-- f92fafbd English: Compare two values using an RM operator identifier: LESSTHAN, LESSTHANOREQUALS,
--     GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS or DIVISIBLE. Invalid operators warn and
--     return nil; operands must support the selected Lua operation.
[2023] = "Zwei Werte mit einer RM-Operatorkennung vergleichen: LESSTHAN, LESSTHANOREQUALS, GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS oder DIVISIBLE. Ungültige Operatoren erzeugen eine Warnung und ergeben nil; die Operanden müssen die gewählte Lua-Operation unterstützen.",
-- 4d1da429 English: Comparison operator key, such as EQUALS or LESSTHAN.
[2024] = "Schlüssel des Vergleichsoperators, etwa EQUALS oder LESSTHAN.",
-- 8d6dc0da English: Comparison result, or nil for an unknown operator.
[2025] = "Vergleichsergebnis oder nil bei einem unbekannten Operator.",
-- 45e7a5a6 English: Comparison text retaining named Boolean alternative markup.
[2026] = "Vergleichstext mit erhaltenem Markup für benannte boolesche Alternativen.",
-- beb1fd9a English: Complete matching class count, including zero, or nil when unavailable.
[2027] = "Vollständige Anzahl passender Klassen, einschließlich null, oder nil, wenn nicht verfügbar.",
-- 3abb0dce English: Complete nonnegative observed count including zero, or nil when unavailable.
[2028] = "Vollständige nichtnegative beobachtete Anzahl einschließlich null oder nil, wenn nicht verfügbar.",
-- a3cbc46a English: Condition container supporting SetLayout, AddChild, SetUserData, SetWidth and
--     DoLayout.
[2029] = "Bedingungscontainer mit Unterstützung für SetLayout, AddChild, SetUserData, SetWidth und DoLayout.",
-- 1edda05a English: Condition value record containing spell, ranked and disabled fields; updated in
--     place.
[2030] = "Bedingungswert-Datensatz mit den Feldern spell, ranked und disabled; wird direkt aktualisiert.",
-- bd948209 English: Condition value record updated when a unit is chosen.
[2031] = "Bedingungswert-Datensatz, der bei Auswahl einer Einheit aktualisiert wird.",
-- 49082497 English: Configured unit selector; add it with parent:AddChild(widget).
[2032] = "Konfigurierte Einheitenauswahl; mit parent:AddChild(widget) hinzufügen.",
-- 93e87554 English: Copy a table using tostring of each original key as the destination key. Values
--     retain their original identities. Colliding stringified keys overwrite each other in
--     unspecified pairs traversal order.
[2033] = "Eine Tabelle kopieren, wobei tostring jedes ursprünglichen Schlüssels als Zielschlüssel dient. Werte behalten ihre ursprüngliche Identität. Kollidierende, in Zeichenketten umgewandelte Schlüssel überschreiben einander in nicht festgelegter pairs-Durchlaufreihenfolge.",
-- dcd01801 English: Count all entries visited by pairs, including false values and sparse numeric
--     or nonnumeric keys. A nil table has length zero.
[2034] = "Alle von pairs besuchten Einträge zählen, einschließlich false-Werten und dünn besetzter numerischer oder nichtnumerischer Schlüssel. Eine nil-Tabelle hat die Länge null.",
-- 7ee6eac7 English: Count matching class tokens in the current fixed roster. Read group membership
--     first; when requested, raid membership selects raid1 through raid40 without a separate player
--     fact. Solo and party paths read player first, then party1 through party4 when grouped. A
--     complete known roster returns a count, including zero; any required unavailable fact returns
--     nil with a reason. Complete observations share the evaluation-pass cache; no player class
--     persists across passes. Archived raw callbacks retain their original load-time class
--     separately.
[2035] = "Passende Klassenkennungen in der aktuellen festen Mitgliederliste zählen. Zuerst die Gruppenzugehörigkeit lesen; auf Anforderung wählt die Schlachtzugszugehörigkeit raid1 bis raid40 ohne separaten Spielerfakt. Solo- und Gruppenpfade lesen zuerst player, dann bei Gruppenzugehörigkeit party1 bis party4. Eine vollständig bekannte Mitgliederliste ergibt eine Anzahl, auch null; jeder erforderliche nicht verfügbare Fakt ergibt nil mit einem Grund. Vollständige Beobachtungen teilen sich den Cache des Auswertungsdurchlaufs; keine Spielerklasse bleibt über Durchläufe hinweg erhalten. Archivierte rohe Callbacks behalten ihre ursprüngliche Klasse zur Ladezeit separat.",
-- ddfd3a7c English: Count only GUID-keyed units already in the observed membership snapshot. Verify
--     current token identity before using the published threat observer; known absent or reused
--     tokens are excluded without adding replacements. Complete identity and threat observations
--     share only the supplied evaluation cache, while membership is traversed fresh. Known nonenemy
--     or optional nil threat is not counted; required unreadable, malformed or failed facts make
--     the entire result unavailable. This does not enumerate a complete roster, apply a range
--     filter or modify tracked records.
[2036] = "Nur Einheiten mit GUID-Schlüssel zählen, die bereits in der beobachteten Momentaufnahme der Zugehörigkeit stehen. Vor Verwendung des veröffentlichten Bedrohungsbeobachters die aktuelle Identität der Kennung prüfen; bekannt abwesende oder wiederverwendete Kennungen werden ausgeschlossen, ohne Ersatz hinzuzufügen. Vollständige Identitäts- und Bedrohungsbeobachtungen teilen sich nur den übergebenen Auswertungs-Cache, während die Zugehörigkeit neu durchlaufen wird. Bekannte Nicht-Feinde oder optionale nil-Bedrohung werden nicht gezählt; erforderliche unlesbare, fehlerhafte oder fehlgeschlagene Fakten machen das gesamte Ergebnis nicht verfügbar. Dies zählt keine vollständige Mitgliederliste auf, wendet keinen Reichweitenfilter an und ändert keine verfolgten Datensätze.",
-- 02e149c6 English: Create a condition field container with RM-owned List, Table and responsive
--     spell-field layouts. It accepts registered native condition widgets; add children with
--     AddChild and attach the group to the callback parent.
[2037] = "Einen Feldcontainer für Bedingungen mit RM-eigenen Layouts List, Table und responsivem Zauberfeld erstellen. Er akzeptiert registrierte native Bedingungs-Widgets; Kinder mit AddChild hinzufügen und die Gruppe an das Callback-Elternelement anhängen.",
-- 24b26357 English: Create a configured unit selector bound to a condition value record. Returns
--     the widget for the caller to add to the condition callback parent.
[2038] = "Eine konfigurierte Einheitenauswahl erstellen, die an einen Bedingungswert-Datensatz gebunden ist. Gibt das Widget zurück, das der Aufrufer dem Callback-Elternelement der Bedingung hinzufügt.",
-- 704feebd English: Create a native boolean condition control. Configure SetLabel, SetValue,
--     SetDisabled and OnValueChanged; add it with parent:AddChild(widget).
[2039] = "Ein natives boolesches Bedingungssteuerelement erstellen. SetLabel, SetValue, SetDisabled und OnValueChanged konfigurieren; mit parent:AddChild(widget) hinzufügen.",
-- d67fc3b8 English: Create a native button using the shared condition widget lifecycle and
--     workbench theme. SetText, SetDisabled and SetCallback configure its label and interaction;
--     OnClick receives the mouse button. Add it to the callback parent with
--     parent:AddChild(widget).
[2040] = "Einen nativen Button mit dem gemeinsamen Widget-Lebenszyklus für Bedingungen und dem Workbench-Design erstellen. SetText, SetDisabled und SetCallback konfigurieren Beschriftung und Interaktion; OnClick erhält die Maustaste. Mit parent:AddChild(widget) dem Callback-Elternelement hinzufügen.",
-- d4341110 English: Create a native condition selector. SetList accepts key-to-label or
--     key-to-entry maps; SetValue selects a key and OnValueChanged reports changes. Add it with
--     parent:AddChild(widget).
[2041] = "Eine native Bedingungsauswahl erstellen. SetList akzeptiert Zuordnungen von Schlüssel zu Beschriftung oder von Schlüssel zu Eintrag; SetValue wählt einen Schlüssel und OnValueChanged meldet Änderungen. Mit parent:AddChild(widget) hinzufügen.",
-- e149229e English: Create a native image control using the condition widget lifecycle. SetImage
--     and SetImageSize choose the texture; SetText optionally adds a caption. OnClick, OnEnter and
--     OnLeave use the shared callback contract. Add the control to the callback parent with
--     parent:AddChild(widget).
[2042] = "Ein natives Bildsteuerelement mit dem Widget-Lebenszyklus für Bedingungen erstellen. SetImage und SetImageSize wählen die Textur; SetText fügt optional eine Beschriftung hinzu. OnClick, OnEnter und OnLeave verwenden den gemeinsamen Callback-Vertrag. Das Steuerelement mit parent:AddChild(widget) dem Callback-Elternelement hinzufügen.",
-- b943d164 English: Create a native numeric condition input with a slider and typed numeric field.
--     Configure SetSliderValues, SetValue, SetIsPercent and SetCallback; OnValueChanged reports
--     committed values. Add it with parent:AddChild(widget).
[2043] = "Eine native numerische Bedingungseingabe mit Schieberegler und Zahlenfeld erstellen. SetSliderValues, SetValue, SetIsPercent und SetCallback konfigurieren; OnValueChanged meldet festgelegte Werte. Mit parent:AddChild(widget) hinzufügen.",
-- a67c621c English: Create a native position pad using the shared directional controls.
--     OnOffsetChanged reports horizontal and vertical direction, whether Center was pressed, and
--     the increment (one, or ten with Shift). SetDisabled controls interaction; add the pad to the
--     callback parent with parent:AddChild(widget).
[2044] = "Ein natives Positionsfeld mit den gemeinsamen Richtungssteuerelementen erstellen. OnOffsetChanged meldet horizontale und vertikale Richtung, ob „Mitte“ gedrückt wurde, und die Schrittweite (eins, oder zehn mit der Umschalttaste). SetDisabled steuert die Interaktion; das Feld mit parent:AddChild(widget) dem Callback-Elternelement hinzufügen.",
-- 25defe9e English: Create a native text input using the condition widget contract. SetLabel,
--     SetText, SetDisabled and SetCallback configure it; OnEnterPressed commits text. Add it to the
--     callback parent with parent:AddChild(widget).
[2045] = "Eine native Texteingabe nach dem Widget-Vertrag für Bedingungen erstellen. SetLabel, SetText, SetDisabled und SetCallback konfigurieren sie; OnEnterPressed übernimmt den Text. Mit parent:AddChild(widget) dem Callback-Elternelement hinzufügen.",
-- edff3bd0 English: Create a shallow filtered copy despite the historical deepcopy name. Nested
--     values retain their original identities and the source metatable is not copied. By default
--     exclude keys listed among except values; invert true includes only listed keys. Nil input
--     returns nil.
[2046] = "Trotz des historischen Namens deepcopy eine flache gefilterte Kopie erstellen. Verschachtelte Werte behalten ihre ursprüngliche Identität, und die Metatabelle der Quelle wird nicht kopiert. Standardmäßig werden Schlüssel ausgeschlossen, die unter den except-Werten aufgeführt sind; invert true schließt nur die aufgeführten Schlüssel ein. Eingabe nil ergibt nil.",
-- ccc11c66 English: Create a spell input with suggestions, validation and spell-link support for
--     custom condition widgets. The update callback owns saving a chosen value; add the returned
--     widget to the callback parent.
[2047] = "Eine Zaubereingabe mit Vorschlägen, Validierung und Zauberlink-Unterstützung für Widgets benutzerdefinierter Bedingungen erstellen. Der Update-Callback ist für das Speichern eines gewählten Werts zuständig; das zurückgegebene Widget dem Callback-Elternelement hinzufügen.",
-- 4736bce4 English: Create a transient named condition summary. Use {name} for scalar values and
--     {{positive|negative}} for predicate alternatives; prefix a primary alternative with !. Escape
--     literal double braces as {{{{ and }}}}. Values are inserted literally without parsing their
--     percent signs, links, colors or braces. Typed predicate values participate in primary
--     selection. Templates, values and rendered text are bounded; malformed input renders a
--     localized unavailable summary. This changes presentation only and runs no condition
--     observations.
[2048] = "Eine flüchtige benannte Bedingungszusammenfassung erstellen. {name} für Skalarwerte und {{positiv|negativ}} für Prädikatalternativen verwenden; einer primären Alternative ! voranstellen. Literale doppelte geschweifte Klammern als {{{{ und }}}} maskieren. Werte werden wörtlich eingefügt, ohne ihre Prozentzeichen, Links, Farben oder Klammern auszuwerten. Typisierte Prädikatwerte nehmen an der Primärauswahl teil. Vorlagen, Werte und gerenderter Text sind begrenzt; fehlerhafte Eingaben ergeben eine lokalisierte Zusammenfassung „nicht verfügbar“. Dies ändert nur die Darstellung und führt keine Bedingungsbeobachtungen aus.",
-- 7735b638 English: Create a typed comparison predicate for a named condition phrase. Positive
--     wording uses the original captured operator map and negative wording uses the current negated
--     operator map. A primary predicate takes precedence over qualifiers; only the first eligible
--     predicate negates. Unknown operators use the existing operator placeholder. This formats
--     wording without comparing values or evaluating a condition.
[2049] = "Ein typisiertes Vergleichsprädikat für eine benannte Bedingungsphrase erstellen. Positive Formulierungen verwenden die ursprünglich erfasste Operatortabelle, negative die aktuelle negierte Operatortabelle. Ein primäres Prädikat hat Vorrang vor Qualifizierern; nur das erste geeignete Prädikat wird negiert. Unbekannte Operatoren verwenden den vorhandenen Operator-Platzhalter. Dies formatiert die Formulierung, ohne Werte zu vergleichen oder eine Bedingung auszuwerten.",
-- ddea308b English: Create an iterator over a sorted snapshot of table keys. Default ordering
--     compares keys; a custom order callback receives the original table and two keys. Values are
--     read from the original table when each key is yielded. The legacy iterator ends when the next
--     captured key is nil or false.
[2050] = "Einen Iterator über eine sortierte Momentaufnahme der Tabellenschlüssel erstellen. Die Standardreihenfolge vergleicht Schlüssel; ein benutzerdefinierter Sortier-Callback erhält die ursprüngliche Tabelle und zwei Schlüssel. Werte werden aus der ursprünglichen Tabelle gelesen, wenn der jeweilige Schlüssel geliefert wird. Der alte Iterator endet, wenn der nächste erfasste Schlüssel nil oder false ist.",
-- 629b2567 English: Create native wrapping text that measures its height from its width and font.
--     SetText, SetFont or SetFontObject configure its contents. Add it to the callback parent with
--     parent:AddChild(widget) so layout can track its measured height.
[2051] = "Nativen umbrechenden Text erstellen, der seine Höhe aus Breite und Schriftart misst. SetText, SetFont oder SetFontObject konfigurieren den Inhalt. Mit parent:AddChild(widget) dem Callback-Elternelement hinzufügen, damit das Layout die gemessene Höhe verfolgen kann.",
-- c58c9a9a English: Create native wrapping text with optional leading image and pointer callbacks.
--     SetImage and SetImageSize configure the image; OnEnter, OnLeave and OnClick use the condition
--     callback contract. Add it to the callback parent with parent:AddChild(widget); callbacks
--     expire when its lease is released.
[2052] = "Nativen umbrechenden Text mit optionalem vorangestelltem Bild und Zeiger-Callbacks erstellen. SetImage und SetImageSize konfigurieren das Bild; OnEnter, OnLeave und OnClick verwenden den Callback-Vertrag für Bedingungen. Mit parent:AddChild(widget) dem Callback-Elternelement hinzufügen; Callbacks verfallen, wenn seine Lease freigegeben wird.",
-- fa988d31 English: Current evaluation time in seconds from GetTime(), normally evalStart.
[2053] = "Aktuelle Auswertungszeit in Sekunden aus GetTime(), normalerweise evalStart.",
-- c7fd7453 English: Current positive visibility distance in yards; nil when unavailable.
[2054] = "Aktuelle positive Sichtweite in Metern; nil, wenn nicht verfügbar.",
-- 574eed72 English: Current unit token whose distance from the player should be observed.
[2055] = "Aktuelle Einheitenkennung, deren Entfernung zum Spieler beobachtet werden soll.",
-- 83a1023e English: Damage/heals arrays of time/value rows; only selected streams are consumed.
[2056] = "Schadens-/Heilungs-Arrays aus Zeit-/Wert-Zeilen; nur ausgewählte Datenströme werden verarbeitet.",
-- 38e0b44b English: Decimal places, default zero; negative values round to tens or larger powers of
--     ten.
[2057] = "Nachkommastellen, standardmäßig null; negative Werte runden auf Zehner oder höhere Zehnerpotenzen.",
-- c1094708 English: Dense array of keys sorted by associated value.
[2058] = "Dichtes Array von Schlüsseln, sortiert nach zugehörigem Wert.",
-- 7de55bf4 English: Dense array of nonempty text fields.
[2059] = "Dichtes Array nichtleerer Textfelder.",
-- ba17b32f English: Destination array modified in place.
[2060] = "Ziel-Array, das direkt verändert wird.",
-- 9d65688a English: Display lookup table.
[2061] = "Nachschlagetabelle für die Anzeige.",
-- 763bf095 English: Estimate signed health change from weighted damage and healing history. Damage
--     contributes a negative rate and healing a positive rate. Read the live profile window when no
--     window is supplied, use the live clock and legacy rounding service, and preserve the existing
--     weighting and rounded-age calculation. This helper does not validate or sanitize history,
--     clamp timestamps, or guarantee finite results.
[2062] = "Vorzeichenbehaftete Gesundheitsänderung aus gewichtetem Schadens- und Heilungsverlauf schätzen. Schaden trägt eine negative Rate bei, Heilung eine positive. Ohne übergebenes Fenster das Live-Fenster des Profils lesen, die Live-Uhr und den alten Rundungsdienst verwenden und die bestehende Gewichtung und Berechnung des gerundeten Alters beibehalten. Diese Hilfsfunktion validiert oder bereinigt den Verlauf nicht, begrenzt keine Zeitstempel und garantiert keine endlichen Ergebnisse.",
-- c95e98a7 English: Estimate time until selected health. Cache complete native identity and lazy
--     scalar observations per evaluation pass, while provider, history, window, clock and forecast
--     stay live. Exact target equality returns zero before history work. Preserve deliberate
--     no-estimate false and initialized-zero results for zero or opposite rates; required invalid
--     facts, overflow or 4096-unit work exhaustion are unavailable. Never mutate history or invent
--     a partial estimate.
[2063] = "Zeit bis zur ausgewählten Gesundheit schätzen. Vollständige native Identitäts- und verzögerte Skalarbeobachtungen werden pro Auswertungsdurchlauf zwischengespeichert, während Anbieter, Verlauf, Fenster, Uhr und Prognose live bleiben. Exakte Gleichheit mit dem Zielwert ergibt null vor jeder Verlaufsarbeit. Bewusste Ergebnisse false (keine Schätzung) und initialisierte Null bei null oder entgegengesetzten Raten bleiben erhalten; erforderliche ungültige Fakten, Überlauf oder Erschöpfung des Arbeitsbudgets von 4096 Einheiten ergeben „nicht verfügbar“. Der Verlauf wird nie verändert und keine Teilschätzung erfunden.",
-- 52a17c6c English: Evaluation cache, or nil to bypass caching.
[2064] = "Auswertungs-Cache oder nil, um das Zwischenspeichern zu umgehen.",
-- 79697e3a English: Evaluation-pass cache for complete unit observations; nil observes directly.
--     Different selected keys reuse the same unit snapshot.
[2065] = "Cache des Auswertungsdurchlaufs für vollständige Einheitenbeobachtungen; nil beobachtet direkt. Verschiedene ausgewählte Schlüssel verwenden dieselbe Einheiten-Momentaufnahme.",
-- bd88f3f9 English: Evaluation-pass cache, or nil for fresh observations.
[2066] = "Cache des Auswertungsdurchlaufs oder nil für frische Beobachtungen.",
-- d022fab6 English: Evaluation-pass cache, or nil to observe identity directly. Resource mapping is
--     resolved live on each invocation.
[2067] = "Cache des Auswertungsdurchlaufs oder nil, um die Identität direkt zu beobachten. Die Ressourcenzuordnung wird bei jedem Aufruf live aufgelöst.",
-- 0900784b English: Evaluation-pass cache, or nil to observe identity directly. Successful player
--     class observations may use the existing longterm identity cache; resource mapping remains
--     live.
[2068] = "Cache des Auswertungsdurchlaufs oder nil, um die Identität direkt zu beobachten. Erfolgreiche Beobachtungen der Spielerklasse können den vorhandenen Langzeit-Identitäts-Cache nutzen; die Ressourcenzuordnung bleibt live.",
-- 383aa43c English: Evaluation-pass native observation cache; nil queries afresh.
[2069] = "Nativer Beobachtungs-Cache des Auswertungsdurchlaufs; nil fragt neu ab.",
-- bf9ecd5c English: Evaluation-pass presence cache only; name, level and provider history remain
--     fresh.
[2070] = "Nur Anwesenheits-Cache des Auswertungsdurchlaufs; Name, Stufe und Anbieterverlauf bleiben frisch.",
-- 2dbf0453 English: Exact helper-owned player, party1..party4 or raid1..raid40 token.
[2071] = "Exakte, von der Hilfsfunktion verwaltete Kennung player, party1..party4 oder raid1..raid40.",
-- 27bda267 English: Exact integral native rune slot from 1 through 6.
[2072] = "Exakter ganzzahliger nativer Runenplatz von 1 bis 6.",
-- 4fc2d3d1 English: Exact nonempty unit token to observe.
[2073] = "Exakte nichtleere zu beobachtende Einheitenkennung.",
-- c590f11f English: Exact nonempty unit token, passed unchanged.
[2074] = "Exakte, nicht leere Einheitenkennung, unverändert übergeben.",
-- fd8065c0 English: Exact readable recipient name recorded for this cast.
[2075] = "Exakter lesbarer Empfängername, der für diesen Zauber aufgezeichnet wurde.",
-- b05cf3b2 English: Exact selected unit token; only the literal player token may select the TBC
--     combo transport.
[2076] = "Exakte ausgewählte Einheitenkennung; nur die literale Kennung player darf den TBC-Combo-Transport wählen.",
-- 19306e82 English: Exact selected unit token; player class alone may use the successful longterm
--     cache.
[2077] = "Exakte ausgewählte Einheitenkennung; nur die Spielerklasse darf den erfolgreichen Langzeit-Cache verwenden.",
-- af7eabaa English: Exact selected unit token; the attacker remains player.
[2078] = "Exakte ausgewählte Einheitenkennung; der Angreifer bleibt player.",
-- c08ce58e English: Exact unit token checked for existence and passed to the selected metadata API.
[2079] = "Exakte Einheitenkennung, die auf Existenz geprüft und an die gewählte Metadaten-API übergeben wird.",
-- eb750dcd English: Exact unit token passed unchanged to UnitExists and, when required, UnitClass.
[2080] = "Exakte Einheitenkennung, unverändert an UnitExists und bei Bedarf an UnitClass übergeben.",
-- 3641c328 English: Exact unit token used for existence and as the recipient of player hostility
--     and threat queries.
[2081] = "Exakte Einheitenkennung, die für die Existenzprüfung und als Empfänger der Feindseligkeits- und Bedrohungsabfragen des Spielers dient.",
-- 616ee642 English: Exact unit token whose resource should be observed; this does not redirect
--     player or vehicle units.
[2082] = "Exakte Einheitenkennung, deren Ressource beobachtet werden soll; Spieler- oder Fahrzeugeinheiten werden nicht umgeleitet.",
-- f89b30c5 English: Exact unit token whose selected flag should be observed.
[2083] = "Exakte Einheitenkennung, deren ausgewähltes Flag beobachtet werden soll.",
-- bb716e79 English: Exact unit token whose selected resource quantity is requested.
[2084] = "Exakte Einheitenkennung, deren ausgewählte Ressourcenmenge angefragt wird.",
-- d07d5f8c English: Exactly current for UnitPower or maximum for UnitPowerMax.
[2085] = "Genau current für UnitPower oder maximum für UnitPowerMax.",
-- 3234a7b8 English: Exactly current for UnitPower or maximum for UnitPowerMax; no other native
--     query is added.
[2086] = "Genau current für UnitPower oder maximum für UnitPowerMax; keine weitere native Abfrage wird hinzugefügt.",
-- ce5b4817 English: Exactly current for the player/target combo query or maximum for the player
--     capacity query.
[2087] = "Genau current für die Combo-Abfrage player/target oder maximum für die Kapazitätsabfrage des Spielers.",
-- 01112dbd English: Exactly dead for UnitIsDeadOrGhost, or friendly for UnitIsFriend(player, unit).
[2088] = "Genau dead für UnitIsDeadOrGhost oder friendly für UnitIsFriend(player, unit).",
-- 572b3dd2 English: Exactly type or school; selects the required subject field without requiring
--     the other.
[2089] = "Genau type oder school; wählt das erforderliche Subjektfeld, ohne das andere zu benötigen.",
-- 618e2637 English: Existing stored CREATURE key: BEAST, DRAGONKIN, DEMON, ELEMENTAL, GIANT,
--     UNDEAD, HUMANOID, CRITTER, MECHANICAL, OTHER, TOTEM, NONCOMBAT_PET or GAS_CLUUD.
[2090] = "Vorhandener gespeicherter CREATURE-Schlüssel: BEAST, DRAGONKIN, DEMON, ELEMENTAL, GIANT, UNDEAD, HUMANOID, CRITTER, MECHANICAL, OTHER, TOTEM, NONCOMBAT_PET oder GAS_CLUUD.",
-- 93af5992 English: Explicit finite clock snapshot; signed and fractional values remain valid.
[2091] = "Explizite endliche Uhr-Momentaufnahme; vorzeichenbehaftete und gebrochene Werte bleiben gültig.",
-- b6d72a06 English: Explicit finite weighting window; no profile fallback or clamp.
[2092] = "Explizites endliches Gewichtungsfenster; kein Rückgriff auf das Profil, keine Begrenzung.",
-- 8775b9a4 English: Explicit nonnegative integer power selector, false for a known absent unit, or
--     nil when required data is unavailable.
[2093] = "Expliziter nichtnegativer ganzzahliger Ressourcenselektor, false für eine bekannt abwesende Einheit oder nil, wenn erforderliche Daten nicht verfügbar sind.",
-- 593273d6 English: Explicit nonnegative integer selector, false for known unit absence, or nil
--     when required data is unavailable.
[2094] = "Expliziter nichtnegativer ganzzahliger Selektor, false bei bekannter Abwesenheit der Einheit oder nil, wenn erforderliche Daten nicht verfügbar sind.",
-- 18dcc116 English: Explicit readable finite nonnegative integer power selector, including zero.
[2095] = "Expliziter lesbarer endlicher nichtnegativer ganzzahliger Ressourcenselektor, einschließlich null.",
-- 4cb2bf6f English: Explicit readable finite nonnegative integer power selector.
[2096] = "Expliziter, lesbarer, endlicher, nichtnegativer ganzzahliger Ressourcenselektor.",
-- cdbf6c56 English: Finite ETA including zero, false for known absence/no estimate, or nil when
--     unavailable.
[2097] = "Endliche voraussichtliche Restzeit einschließlich null, false bei bekannter Abwesenheit/keiner Schätzung oder nil, wenn nicht verfügbar.",
-- a4382b09 English: Finite final stream age, or nil when unavailable.
[2098] = "Endliches letztes Alter des Datenstroms oder nil, wenn nicht verfügbar.",
-- 84e16e8d English: Finite minimum native threat status, preserving signed and fractional
--     thresholds.
[2099] = "Endlicher minimaler nativer Bedrohungsstatus; vorzeichenbehaftete und gebrochene Schwellenwerte bleiben erhalten.",
-- 7e3a2158 English: Finite native creature ID, false for known unit absence, or nil when required
--     observations are unavailable.
[2100] = "Endliche native Kreatur-ID, false bei bekannter Abwesenheit der Einheit oder nil, wenn erforderliche Beobachtungen nicht verfügbar sind.",
-- 3dd70e07 English: Finite native resource quantity, retaining its sign and fractional part; nil
--     when unavailable.
[2101] = "Endliche native Ressourcenmenge mit Vorzeichen und Nachkommaanteil; nil, wenn nicht verfügbar.",
-- 3931aa80 English: Finite native threat status, false for known absence/nonenemy/no-threat, or nil
--     for unavailable observations.
[2102] = "Endlicher nativer Bedrohungsstatus, false bei bekannter Abwesenheit/Nicht-Feind/keiner Bedrohung oder nil bei nicht verfügbaren Beobachtungen.",
-- 9cb9f6d2 English: Finite nonnegative native health scalar, or nil when unavailable.
[2103] = "Endlicher nichtnegativer nativer Gesundheitswert oder nil, wenn nicht verfügbar.",
-- aa23a412 English: Finite quantity in whole units with its fractional part; nil when unavailable.
[2104] = "Endliche Menge in ganzen Einheiten mit ihrem Bruchteil; nil, wenn nicht verfügbar.",
-- 29e4a6a2 English: Finite signed combined rate, or nil for unavailable calculation.
[2105] = "Endliche vorzeichenbehaftete kombinierte Rate oder nil, wenn die Berechnung nicht verfügbar ist.",
-- 94c010ef English: First exact unit token, checked for existence before comparison.
[2106] = "Erste exakte Einheitenkennung, vor dem Vergleich auf Existenz geprüft.",
-- 46ec876e English: First table to compare.
[2107] = "Erste zu vergleichende Tabelle.",
-- 13e6df72 English: Format comparison wording with named Boolean alternatives when the operator has
--     a negative form. The primary flag marks the positive form as the primary alternative.
--     Positive operator labels use the captured operator map; negative labels and nullable dispatch
--     retain their live addon APIs.
[2108] = "Vergleichsformulierung mit benannten booleschen Alternativen formatieren, wenn der Operator eine negative Form hat. Das Primär-Flag kennzeichnet die positive Form als primäre Alternative. Positive Operatorbeschriftungen verwenden die erfasste Operatortabelle; negative Beschriftungen und die nullable-Weiterleitung behalten ihre Live-Addon-APIs.",
-- b0edcb9b English: Fresh finite native clock value, or nil when unavailable.
[2109] = "Frisch gelesener endlicher nativer Uhrwert oder nil, wenn nicht verfügbar.",
-- b3a296d8 English: Fresh readable class filename, or nil when unavailable.
[2110] = "Frisch gelesener lesbarer Klassen-Dateiname oder nil, wenn nicht verfügbar.",
-- 16428e88 English: Fresh readable finite clock, or nil when unavailable.
[2111] = "Frisch gelesene lesbare endliche Uhrzeit oder nil, wenn nicht verfügbar.",
-- 2078f2c6 English: Fresh readable record with active, then name or nameReason, remainingSeconds,
--     durationSeconds, interruptible and spellID. Remaining time and duration are in seconds;
--     remaining time is clamped to zero. An unavailable optional field has its own reason; it does
--     not invalidate an active record.
[2112] = "Frisch gelesener Datensatz mit active, dann name oder nameReason, remainingSeconds, durationSeconds, interruptible und spellID. Restzeit und Dauer sind in Sekunden angegeben; die Restzeit wird nach unten auf null begrenzt. Ein nicht verfügbares optionales Feld hat seinen eigenen Grund; es macht einen aktiven Datensatz nicht ungültig.",
-- 47a58974 English: Fresh readable record with exists and, when present, a positive integer level.
[2113] = "Frisch gelesener lesbarer Datensatz mit exists und, falls vorhanden, einer positiven ganzzahligen Stufe.",
-- a25abeed English: Fresh readable record with exists and, when present, current health. Maximum
--     health is included only when requested.
[2114] = "Frisch gelesener lesbarer Datensatz mit exists und, falls vorhanden, der aktuellen Gesundheit. Die maximale Gesundheit ist nur enthalten, wenn sie angefragt wird.",
-- 21290700 English: Fresh readable record with exists and, when present, powerType and finite
--     current quantity. Requested maximum is finite and nonnegative. Quantities may be fractional;
--     current-mode current may be signed.
[2115] = "Frisch gelesener lesbarer Datensatz mit exists und, falls vorhanden, powerType und endlicher aktueller Menge. Ein angefragtes Maximum ist endlich und nichtnegativ. Mengen können gebrochen sein; im Modus current kann die aktuelle Menge ein Vorzeichen haben.",
-- 681f8ad6 English: Fresh readable record with finite nonnegative speed, or nil when unavailable.
[2116] = "Frisch gelesener lesbarer Datensatz mit endlicher nichtnegativer Geschwindigkeit oder nil, wenn nicht verfügbar.",
-- abf7477d English: Function or global function name to call.
[2117] = "Aufzurufende Funktion oder Name einer globalen Funktion.",
-- 9d253f49 English: History record with newest-first damage and heals arrays of time/value entries.
--     Falsy history returns only zero without reading the clock.
[2118] = "Verlaufsdatensatz mit den Arrays damage und heals aus Zeit-/Wert-Einträgen, neueste zuerst. Ist der Verlauf nil oder false, wird nur null zurückgegeben, ohne die Uhr zu lesen.",
-- 8deb9947 English: Identifier-keyed scalar values or typed predicates. Strings, finite numbers and
--     booleans are supported; referenced slots must be present. Values are captured when the phrase
--     is created.
[2119] = "Nach Bezeichner indizierte Skalarwerte oder typisierte Prädikate. Zeichenketten, endliche Zahlen und boolesche Werte werden unterstützt; referenzierte Platzhalter müssen vorhanden sein. Werte werden beim Erstellen der Phrase erfasst.",
-- b1c195d7 English: Insert each value visited by ipairs at its corresponding leading index in the
--     destination array. Existing entries shift after the inserted prefix; traversal stops at the
--     first missing source index.
[2120] = "Jeden von ipairs besuchten Wert am entsprechenden vorderen Index in das Ziel-Array einfügen. Vorhandene Einträge verschieben sich hinter das eingefügte Präfix; der Durchlauf endet beim ersten fehlenden Quellindex.",
-- db2baa62 English: Integral RM statistic selector 1..5, or 6 for effective armor.
[2121] = "Ganzzahliger RM-Werteselektor 1..5 oder 6 für effektive Rüstung.",
-- c406e603 English: Iterator yielding a captured key and its current table value, or no values when
--     exhausted.
[2122] = "Iterator, der einen erfassten Schlüssel und seinen aktuellen Tabellenwert liefert, oder keine Werte, wenn er erschöpft ist.",
-- ce63ac6d English: Key to look up.
[2123] = "Nachzuschlagender Schlüssel.",
-- 3638b5da English: Known active count from zero through the RM scan budget, or nil when
--     unavailable.
[2124] = "Bekannte aktive Anzahl von null bis zum RM-Scan-Budget oder nil, wenn nicht verfügbar.",
-- 101d17c0 English: Known nonempty role string, false for known absent unit, or nil when
--     unavailable.
[2125] = "Bekannte nichtleere Rollen-Zeichenkette, false für eine bekannt abwesende Einheit oder nil, wenn nicht verfügbar.",
-- 5194c38b English: Known nonempty role string, or nil when unavailable.
[2126] = "Bekannte nichtleere Rollen-Zeichenkette oder nil, wenn nicht verfügbar.",
-- 74c5fd96 English: Known unit presence or absence; nil when the required observation is
--     unavailable.
[2127] = "Bekannte Anwesenheit oder Abwesenheit der Einheit; nil, wenn die erforderliche Beobachtung nicht verfügbar ist.",
-- 337a2aa3 English: Larger rounded stream age in seconds, not a sample count or proof of continuous
--     observation. Omitted when history is falsy.
[2128] = "Größeres gerundetes Alter des Datenstroms in Sekunden, weder eine Stichprobenzahl noch ein Beleg für lückenlose Beobachtung. Entfällt, wenn der Verlauf nil oder false ist.",
-- 289c0861 English: Left operand; use numbers for ordering and divisibility.
[2129] = "Linker Operand; für Ordnung und Teilbarkeit Zahlen verwenden.",
-- c6b39836 English: Literal prefix, including an empty prefix.
[2130] = "Literales Präfix, auch ein leeres.",
-- 8bc05b19 English: Literal suffix, including an empty suffix.
[2131] = "Literales Suffix, auch ein leeres.",
-- 696821ba English: Live selected talent-group argument, forwarded unchanged as one argument after
--     readability checking.
[2132] = "Live-Argument der ausgewählten Talentgruppe, nach der Lesbarkeitsprüfung unverändert als ein Argument weitergereicht.",
-- 55c2262c English: Localized complete sentence with named slots and optional explicit predicate
--     alternatives.
[2133] = "Lokalisierter vollständiger Satz mit benannten Platzhaltern und optionalen expliziten Prädikatalternativen.",
-- ebab9399 English: Look up a table key for display, preserving non-nil results; invalid tables,
--     missing keys and nil keys use nullable placeholder text.
[2134] = "Einen Tabellenschlüssel zur Anzeige nachschlagen, wobei Ergebnisse ungleich nil erhalten bleiben; ungültige Tabellen, fehlende Schlüssel und nil-Schlüssel verwenden den Platzhaltertext von nullable.",
-- d27c5ef2 English: Lookup key.
[2135] = "Nachschlageschlüssel.",
-- d746509f English: Lua pattern character-class separator, default %s for whitespace.
-- %s #1: %s #1: not a placeholder; it is the literal Lua pattern class for whitespace, shown to the user as text, e.g. "default %s for whitespace". Keep %s exactly as written.
[2136] = "Trennzeichen als Zeichenklasse eines Lua-Musters, standardmäßig %s für Leerraum.",
-- 3aeb0664 English: Mark the positive wording as the primary named alternative.
[2137] = "Die positive Formulierung als primäre benannte Alternative kennzeichnen.",
-- 44dec6d3 English: Matching key, including a false key, or nil when no match exists.
[2138] = "Passender Schlüssel, auch ein Schlüssel false, oder nil, wenn es keine Übereinstimmung gibt.",
-- 75ef3e00 English: Missing-value display text; omitted uses the localized value placeholder.
[2139] = "Anzeigetext für fehlende Werte; ohne Angabe wird der lokalisierte Wert-Platzhalter verwendet.",
-- 15f81670 English: Native button with label, disabled state and lease-protected callbacks.
[2140] = "Nativer Button mit Beschriftung, Deaktivierungsstatus und Lease-geschützten Callbacks.",
-- 8eb10f5d English: Native directional pad with center reset and lease-protected callbacks.
[2141] = "Natives Richtungsfeld mit Zurücksetzen auf die Mitte und Lease-geschützten Callbacks.",
-- bb0ac63a English: Native image control with label, texture, disabled state and callbacks.
[2142] = "Natives Bildsteuerelement mit Beschriftung, Textur, Deaktivierungsstatus und Callbacks.",
-- 43cf01e1 English: Native interactive text and image control with measured height and disabled
--     state.
[2143] = "Natives interaktives Text- und Bildsteuerelement mit gemessener Höhe und Deaktivierungsstatus.",
-- 990a6544 English: Native one-based integral active-row index within the 256-row RM scan budget.
[2144] = "Nativer einsbasierter ganzzahliger Index der aktiven Zeile innerhalb des RM-Scan-Budgets von 256 Zeilen.",
-- 7e3aed01 English: Native wrapping text control with font, color and alignment methods.
[2145] = "Natives umbrechendes Textsteuerelement mit Methoden für Schriftart, Farbe und Ausrichtung.",
-- d76c2067 English: New shallow filtered table, or nil for nil input.
[2146] = "Neue flache gefilterte Tabelle oder nil bei Eingabe nil.",
-- 50f7bd28 English: New table with stringified keys and unchanged values.
[2147] = "Neue Tabelle mit in Zeichenketten umgewandelten Schlüsseln und unveränderten Werten.",
-- f1052f11 English: Newest-first health snapshots containing time, value and max. Falsy input
--     returns only zero without reading the clock.
[2148] = "Gesundheits-Momentaufnahmen mit time, value und max, neueste zuerst. Bei Eingabe nil oder false wird nur null zurückgegeben, ohne die Uhr zu lesen.",
-- 7276d3c4 English: No return values. The destination array is modified in place.
[2149] = "Keine Rückgabewerte. Das Ziel-Array wird direkt verändert.",
-- 69c24773 English: No return values. The supplied table is modified in place.
[2150] = "Keine Rückgabewerte. Die übergebene Tabelle wird direkt verändert.",
-- da87cc23 English: Nonempty class filename token to count; no class-token whitelist is applied.
[2151] = "Zu zählende nichtleere Klassen-Dateinamen-Kennung; es gilt keine Positivliste für Klassenkennungen.",
-- 3694f9ed English: Nonempty historical school key for resist/immune; unused for runner.
[2152] = "Nichtleerer historischer Zauberschul-Schlüssel für resist/immune; für runner ungenutzt.",
-- 7ee44b6f English: Normalized bounded socket snapshot with slots and complete, or nil when the
--     query is unavailable.
[2153] = "Normalisierte begrenzte Sockel-Momentaufnahme mit slots und complete oder nil, wenn die Abfrage nicht verfügbar ist.",
-- 93ec5fb4 English: Normalized requested subject with finite timeRemaining or timeRemainingReason;
--     nil when the required row or subject is unavailable.
[2154] = "Normalisiertes angefragtes Subjekt mit endlichem timeRemaining oder timeRemainingReason; nil, wenn die erforderliche Zeile oder das Subjekt nicht verfügbar ist.",
-- 7663ebe1 English: Number of entries visited.
[2155] = "Anzahl der besuchten Einträge.",
-- 7f36a397 English: Number or string to inspect; other types do not match.
[2156] = "Zu prüfende Zahl oder Zeichenkette; andere Typen passen nicht.",
-- 4e6ddf17 English: Numeric widget supporting slider bounds, percent display and pending-edit
--     validation.
[2157] = "Numerisches Widget mit Schiebereglergrenzen, Prozentanzeige und Validierung ausstehender Bearbeitungen.",
-- c8144d6f English: Observation kind: cast or channel. These use different native interruptibility
--     tuple positions.
[2158] = "Beobachtungsart: cast oder channel. Diese verwenden unterschiedliche Positionen im nativen Tupel für die Unterbrechbarkeit.",
-- 02905e55 English: Observation, history, work-limit or arithmetic availability reason.
[2159] = "Verfügbarkeitsgrund aus Beobachtung, Verlauf, Arbeitslimit oder Arithmetik.",
-- 966b23c3 English: Observe a fresh protected zero-argument GetTime for a needed health forecast.
--     Require readability and a finite number; preserve signed and fractional values without adding
--     a monotonic, integral or nonnegative restriction. No clock cache or extra native query is
--     used.
[2160] = "Ein frisches geschütztes GetTime ohne Argumente für eine benötigte Gesundheitsprognose beobachten. Lesbarkeit und eine endliche Zahl sind erforderlich; vorzeichenbehaftete und gebrochene Werte bleiben erhalten, ohne eine Einschränkung auf monoton, ganzzahlig oder nichtnegativ hinzuzufügen. Es wird kein Uhr-Cache und keine zusätzliche native Abfrage verwendet.",
-- 9d79dc0d English: Observe a point resource that the client reports in fragments (Mists of
--     Pandaria Burning Embers). Current uses exactly UnitPower(unit,powerType,true) and maximum
--     UnitPowerMax(unit,powerType,true); the result is divided by Blizzard MAX_POWER_PER_EMBER
--     (10), so 35 fragments are 3.5. Probe policy only. Missing, failed, restricted or malformed
--     data remains unavailable; it never falls back to the whole-unit query. No cache is added.
[2161] = "Eine Punktressource beobachten, die der Client in Fragmenten meldet (Instabile Funken in Mists of Pandaria). current verwendet genau UnitPower(unit,powerType,true) und maximum UnitPowerMax(unit,powerType,true); das Ergebnis wird durch Blizzards MAX_POWER_PER_EMBER (10) geteilt, sodass 35 Fragmente 3,5 ergeben. Nur Probe-Richtlinie. Fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Daten bleiben nicht verfügbar; es wird nie auf die Abfrage in ganzen Einheiten zurückgefallen. Es wird kein Cache hinzugefügt.",
-- eb0c20b2 English: Observe a readable raw unit level on known clients. A readable absent unit
--     returns exists=false; present units require a positive finite integer UnitLevel. Unknown boss
--     levels, missing, failed, restricted or malformed observations return nil with a reason. This
--     does not use effective or scaled levels.
[2162] = "Eine lesbare rohe Einheitenstufe auf bekannten Clients beobachten. Eine lesbar abwesende Einheit ergibt exists=false; vorhandene Einheiten erfordern eine positive endliche ganzzahlige UnitLevel. Unbekannte Bossstufen sowie fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Beobachtungen ergeben nil mit einem Grund. Effektive oder skalierte Stufen werden nicht verwendet.",
-- bc5313d0 English: Observe a selected unit role on probe- and restricted-policy clients without
--     issuing inspection requests. Known unit absence returns false. Prefer the callable modern
--     inspection API, with legacy fallback only when that callable is absent; a selected failure
--     never falls through. Require a positive finite integral specialization ID and consume only
--     role return five from the exact one-argument GetSpecializationInfoByID call. Missing, failed,
--     restricted or malformed required facts are unavailable; readable nonempty future role strings
--     remain exact.
[2163] = "Die Rolle einer ausgewählten Einheit auf Clients mit Probe- oder Restricted-Richtlinie beobachten, ohne Betrachtungsanfragen auszulösen. Bekannte Abwesenheit der Einheit ergibt false. Die aufrufbare moderne Betrachtungs-API wird bevorzugt; auf die alte wird nur zurückgegriffen, wenn diese fehlt, und ein Fehlschlag der gewählten API fällt nie auf die andere zurück. Erforderlich ist eine positive endliche ganzzahlige Spezialisierungs-ID; verwendet wird nur Rückgabewert fünf (Rolle) des exakten Aufrufs GetSpecializationInfoByID mit einem Argument. Fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte erforderliche Fakten sind nicht verfügbar; lesbare nichtleere künftige Rollen-Zeichenketten bleiben exakt erhalten.",
-- 3668cf1e English: Observe a unit casting or channeling on probe- and restricted-policy clients. A
--     known absent unit or a readable inactive result returns active=false. Active records contain
--     name, or nameReason when the name is secret (the unit is still casting), and independently
--     available remainingSeconds, durationSeconds, interruptible and spellID fields, with
--     remainingReason, durationReason, interruptibleReason or spellReason when an optional field is
--     unavailable. Missing, failed or restricted presence observations return nil with a reason.
[2164] = "Wirken oder Kanalisieren einer Einheit auf Clients mit Probe- oder Restricted-Richtlinie beobachten. Eine bekannt abwesende Einheit oder ein lesbares inaktives Ergebnis ergibt active=false. Aktive Datensätze enthalten name, oder nameReason, wenn der Name geheim ist (die Einheit wirkt dennoch), sowie die unabhängig verfügbaren Felder remainingSeconds, durationSeconds, interruptible und spellID, mit remainingReason, durationReason, interruptibleReason oder spellReason, wenn ein optionales Feld nicht verfügbar ist. Fehlende, fehlgeschlagene oder eingeschränkte Anwesenheitsbeobachtungen ergeben nil mit einem Grund.",
-- 740dd187 English: Observe creature identity from native UnitCreatureType return two on probe- and
--     restricted-policy clients. Check exact UnitExists(unit) first; readable false returns false
--     without requiring or calling creature metadata. A present unit requires a readable finite
--     numeric ID; the unused localized name does not affect availability. Preserve signed,
--     fractional, zero and future finite IDs as known values. Missing, failed, nil, restricted or
--     malformed required facts return nil with a reason. No creature enumeration, translated
--     caption comparison or longterm cache is added.
[2165] = "Die Kreaturidentität aus Rückgabewert zwei des nativen UnitCreatureType auf Clients mit Probe- oder Restricted-Richtlinie beobachten. Zuerst exakt UnitExists(unit) prüfen; ein lesbares false ergibt false, ohne Kreaturmetadaten zu benötigen oder abzufragen. Eine vorhandene Einheit erfordert eine lesbare endliche numerische ID; der ungenutzte lokalisierte Name beeinflusst die Verfügbarkeit nicht. Vorzeichenbehaftete, gebrochene, Null- und künftige endliche IDs bleiben als bekannte Werte erhalten. Fehlende, fehlgeschlagene, nil-, eingeschränkte oder fehlerhafte erforderliche Fakten ergeben nil mit einem Grund. Es wird keine Kreaturaufzählung, kein Vergleich übersetzter Beschriftungen und kein Langzeit-Cache hinzugefügt.",
-- 075b71e7 English: Observe death or ghost state, or friendliness to the player, for the exact
--     selected unit on probe- and restricted-policy clients. A missing, failed, restricted or
--     malformed required observation is unavailable. Unit absence is unavailable rather than a
--     negative match, including under NOT. No cross-poll state is retained.
[2166] = "Tod- oder Geisterzustand bzw. Freundlichkeit gegenüber dem Spieler für die exakt ausgewählte Einheit auf Clients mit Probe- oder Restricted-Richtlinie beobachten. Eine fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte erforderliche Beobachtung ist nicht verfügbar. Abwesenheit der Einheit gilt als nicht verfügbar statt als negativer Treffer, auch unter NOT. Es wird kein Zustand zwischen Abfragen beibehalten.",
-- 87176204 English: Observe exact pet existence and optionally its formatted GetUnitName display
--     name. Presence-only queries never require name data. Known absence skips the name query.
--     Present pets require a readable nonempty name only when requested; required missing, failed,
--     nil, restricted or malformed observations return nil with a reason. The display helper is
--     called with its single original pet argument, without UnitName fallback or inferred bar,
--     health or ability state.
[2167] = "Die exakte Existenz des Begleiters und optional seinen formatierten Anzeigenamen per GetUnitName beobachten. Reine Anwesenheitsabfragen benötigen nie Namensdaten. Bekannte Abwesenheit überspringt die Namensabfrage. Vorhandene Begleiter benötigen nur auf Anfrage einen lesbaren nichtleeren Namen; erforderliche fehlende, fehlgeschlagene, nil-, eingeschränkte oder fehlerhafte Beobachtungen ergeben nil mit einem Grund. Die Anzeigehilfsfunktion wird mit ihrem einzigen ursprünglichen Argument pet aufgerufen, ohne Rückgriff auf UnitName und ohne abgeleiteten Leisten-, Gesundheits- oder Fähigkeitszustand.",
-- 2280ad22 English: Observe exact selected-unit existence and optionally its class filename for
--     point-resource conditions. Known absence returns exists=false without reading class. Present
--     units require only UnitClass return two when requested; unused localized names and IDs do not
--     affect availability. Required missing, failed, restricted or malformed observations remain
--     unavailable. This does not select a resource or cache identity.
[2168] = "Für Punktressourcen-Bedingungen die exakte Existenz der ausgewählten Einheit und optional ihren Klassen-Dateinamen beobachten. Bekannte Abwesenheit ergibt exists=false, ohne die Klasse zu lesen. Vorhandene Einheiten benötigen auf Anfrage nur Rückgabewert zwei von UnitClass; ungenutzte lokalisierte Namen und IDs beeinflussen die Verfügbarkeit nicht. Erforderliche fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Beobachtungen bleiben nicht verfügbar. Dies wählt keine Ressource aus und speichert keine Identität zwischen.",
-- 9b79981c English: Observe explicit mana or the current raw power resource on supported readable
--     clients. Select resource identities from the live PowerType enum; explicit mana never falls
--     back to the current bar. Known absence returns exists=false; missing, failed, restricted or
--     malformed observations return nil with a reason. Current-mode quantities preserve signed
--     native resources; explicit mana is nonnegative. Request maximum only when needed; percentage
--     consumers must require a positive maximum.
[2169] = "Explizit Mana oder die aktuelle rohe Ressource auf unterstützten lesbaren Clients beobachten. Ressourcenidentitäten werden aus dem Live-Enum PowerType gewählt; explizites Mana fällt nie auf die aktuelle Leiste zurück. Bekannte Abwesenheit ergibt exists=false; fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Beobachtungen ergeben nil mit einem Grund. Mengen im Modus current behalten vorzeichenbehaftete native Ressourcen bei; explizites Mana ist nichtnegativ. Das Maximum nur bei Bedarf anfragen; prozentuale Verbraucher müssen ein positives Maximum verlangen.",
-- 278a17a4 English: Observe glyph sockets on verified Wrath, Cata and Mists client layouts. Returns
--     slots and a complete flag. Each slot has active=false when known locked or empty, active=true
--     plus spellID when occupied, or nil active plus reason when unavailable. Unknown layouts and
--     failed count queries return nil with a reason. This does not compare item names or prove
--     exact item-to-spell identity.
[2170] = "Glyphensockel auf verifizierten Client-Layouts von Wrath, Cata und Mists beobachten. Gibt slots und ein Flag complete zurück. Jeder Platz hat active=false, wenn er bekanntermaßen gesperrt oder leer ist, active=true plus spellID, wenn er belegt ist, oder active nil plus Grund, wenn er nicht verfügbar ist. Unbekannte Layouts und fehlgeschlagene Anzahlabfragen ergeben nil mit einem Grund. Dies vergleicht keine Gegenstandsnamen und belegt keine exakte Identität von Gegenstand und Zauber.",
-- 24ad932a English: Observe one consumed native unit metadata field after checking UnitExists:
--     class uses UnitClass return two, creature uses the localized UnitCreatureType name, and
--     classification uses UnitClassification. A readable absent unit returns false without querying
--     metadata. Unused tuple fields do not affect availability; a required missing, failed, nil,
--     restricted or malformed value returns nil with a reason. No player class, GUID, enum or
--     translation inference is added.
[2171] = "Nach Prüfung von UnitExists genau ein verwendetes natives Metadatenfeld der Einheit beobachten: class nutzt Rückgabewert zwei von UnitClass, creature den lokalisierten Namen aus UnitCreatureType und classification UnitClassification. Eine lesbar abwesende Einheit ergibt false, ohne Metadaten abzufragen. Ungenutzte Tupelfelder beeinflussen die Verfügbarkeit nicht; ein erforderlicher fehlender, fehlgeschlagener, nil-, eingeschränkter oder fehlerhafter Wert ergibt nil mit einem Grund. Es wird keine Ableitung von Spielerklasse, GUID, Enum oder Übersetzung hinzugefügt.",
-- 641cce1a English: Observe one current unit flag: combat uses UnitAffectingCombat, enemy uses
--     UnitIsEnemy with player as the first unit, and pvp uses UnitIsPVP. A readable absent unit
--     returns false without querying the flag. Required missing, failed, restricted or malformed
--     observations return nil with a reason. This preserves the exact selected unit and does not
--     infer friendliness, attackability or other unit states.
[2172] = "Ein aktuelles Einheiten-Flag beobachten: combat nutzt UnitAffectingCombat, enemy nutzt UnitIsEnemy mit player als erster Einheit und pvp nutzt UnitIsPVP. Eine lesbar abwesende Einheit ergibt false, ohne das Flag abzufragen. Erforderliche fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Beobachtungen ergeben nil mit einem Grund. Die exakt ausgewählte Einheit bleibt erhalten; Freundlichkeit, Angreifbarkeit oder andere Einheitenzustände werden nicht abgeleitet.",
-- abc3ec81 English: Observe one exact native rune slot using GetRuneType with its single index
--     argument. Require a readable finite positive integral type; known future numeric types remain
--     distinct from the selected type, and Death is an exact type rather than a wildcard. Missing,
--     failed, restricted or malformed observations remain unavailable. No class, unit, count or
--     inferred base-rune query is added.
[2173] = "Einen exakten nativen Runenplatz mit GetRuneType und seinem einzigen Index-Argument beobachten. Erforderlich ist ein lesbarer endlicher positiver ganzzahliger Typ; bekannte künftige numerische Typen bleiben vom ausgewählten Typ unterscheidbar, und die Todesrune ist ein exakter Typ, kein Joker. Fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Beobachtungen bleiben nicht verfügbar. Es wird keine Abfrage von Klasse, Einheit, Anzahl oder abgeleiteter Basisrune hinzugefügt.",
-- 87dc4eea English: Observe one independent zero-argument player flag: stealthed uses IsStealthed,
--     control uses HasFullControl, and outdoors uses IsOutdoors. Readable true and false retain
--     their meanings. Required missing, failed, nil, restricted or malformed data returns nil with
--     a reason. No existence, instance or ability-usability inference is added.
[2174] = "Ein unabhängiges Spieler-Flag ohne Argumente beobachten: stealthed nutzt IsStealthed, control nutzt HasFullControl und outdoors nutzt IsOutdoors. Lesbares true und false behalten ihre Bedeutung. Erforderliche fehlende, fehlgeschlagene, nil-, eingeschränkte oder fehlerhafte Daten ergeben nil mit einem Grund. Es wird keine Ableitung von Existenz, Instanz oder Fähigkeitsnutzbarkeit hinzugefügt.",
-- 46d51f29 English: Observe one protected zero-argument IsInInstance tuple. Required readable
--     Boolean membership is independent of the type field: known outside returns without
--     interpreting the unused type; inside returns a readable string type or an instanceTypeReason
--     when that secondary field is unavailable. Callers testing outside need only membership;
--     inside type comparisons must check the secondary reason. No outdoors, zone or unit inference
--     is added.
[2175] = "Ein geschütztes IsInInstance-Tupel ohne Argumente beobachten. Die erforderliche lesbare boolesche Zugehörigkeit ist unabhängig vom Typfeld: bekannt außerhalb kehrt zurück, ohne den ungenutzten Typ auszuwerten; innerhalb liefert einen lesbaren Zeichenketten-Typ oder instanceTypeReason, wenn dieses zweite Feld nicht verfügbar ist. Aufrufer, die auf „außerhalb“ prüfen, benötigen nur die Zugehörigkeit; Typvergleiche für „innerhalb“ müssen den zweiten Grund prüfen. Es wird keine Ableitung von Außenbereich, Zone oder Einheit hinzugefügt.",
-- 5671d2c8 English: Observe ordered selected-unit existence, hostility from player, then the player
--     threat status on that unit. Known absence, nonenemy and a successfully read nil threat status
--     return false, preserving the no-threat predicate. Finite status numbers including zero retain
--     their original comparison meaning. Required missing, failed, nil, restricted or malformed
--     facts return nil with a reason. No attackability, death, combat or vehicle inference is
--     added.
[2176] = "Der Reihe nach die Existenz der ausgewählten Einheit, ihre Feindseligkeit gegenüber dem Spieler und dann den Bedrohungsstatus des Spielers auf dieser Einheit beobachten. Bekannte Abwesenheit, Nicht-Feind und ein erfolgreich gelesener nil-Bedrohungsstatus ergeben false, sodass das Prädikat „keine Bedrohung“ erhalten bleibt. Endliche Statuszahlen einschließlich null behalten ihre ursprüngliche Vergleichsbedeutung. Erforderliche fehlende, fehlgeschlagene, nil-, eingeschränkte oder fehlerhafte Fakten ergeben nil mit einem Grund. Es wird keine Ableitung von Angreifbarkeit, Tod, Kampf oder Fahrzeug hinzugefügt.",
-- 545656e0 English: Observe readable current health and optionally maximum health on supported
--     clients. A readable absent unit returns exists=false. Missing, failed, restricted or
--     malformed observations return nil with a reason; they do not establish an absent unit or a
--     health value.
[2177] = "Lesbare aktuelle Gesundheit und optional die maximale Gesundheit auf unterstützten Clients beobachten. Eine lesbar abwesende Einheit ergibt exists=false. Fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Beobachtungen ergeben nil mit einem Grund; sie belegen weder eine abwesende Einheit noch einen Gesundheitswert.",
-- 254b0aeb English: Observe the current player form with one protected zero-argument
--     GetShapeshiftForm call. Preserve every readable finite numeric result, including zero, signed
--     and fractional values; no stronger native index domain is inferred. Missing, failed, nil,
--     restricted or nonfinite data remains unavailable. No form count, class, spell ID, unit or
--     optional argument is added.
[2178] = "Die aktuelle Gestalt des Spielers mit einem geschützten Aufruf von GetShapeshiftForm ohne Argumente beobachten. Jedes lesbare endliche numerische Ergebnis bleibt erhalten, einschließlich null, vorzeichenbehafteter und gebrochener Werte; es wird kein strengerer nativer Indexbereich abgeleitet. Fehlende, fehlgeschlagene, nil-, eingeschränkte oder nicht endliche Daten bleiben nicht verfügbar. Es wird keine Gestaltanzahl, Klasse, Zauber-ID, Einheit und kein optionales Argument hinzugefügt.",
-- 1de1b681 English: Observe the effective statistic from native return two only. On probe- and
--     restricted-policy clients, query exact UnitExists(unit), then UnitStat(unit,stat) for
--     selector 1..5 or UnitArmor(unit) for selector 6. Known absence returns exists=false; missing,
--     failed, restricted or nonfinite required facts return nil. Preserve finite signed, fractional
--     and zero values; ignore all unused tuple fields. The 1..6 route is an RM selector policy, not
--     a native value-domain limit.
[2179] = "Den effektiven Wert nur aus dem nativen Rückgabewert zwei beobachten. Auf Clients mit Probe- oder Restricted-Richtlinie exakt UnitExists(unit) abfragen, dann UnitStat(unit,stat) für Selektor 1..5 oder UnitArmor(unit) für Selektor 6. Bekannte Abwesenheit ergibt exists=false; fehlende, fehlgeschlagene, eingeschränkte oder nicht endliche erforderliche Fakten ergeben nil. Endliche vorzeichenbehaftete, gebrochene und Nullwerte bleiben erhalten; alle ungenutzten Tupelfelder werden ignoriert. Der Bereich 1..6 ist eine Selektorrichtlinie von RM, keine Grenze des nativen Wertebereichs.",
-- 2cf23a04 English: Observe the explicitly selected TBC player combo transport. Current uses
--     exactly GetComboPoints(player,target); maximum uses UnitPowerMax(player,powerType) with the
--     original selector. Other families are unavailable here and must use their existing
--     point-power observer. Preserve readable finite signed, fractional and zero values. Missing,
--     failed, restricted or malformed data remains unavailable; a failed chosen combo query never
--     falls back to UnitPower. This observes no other actor and adds no cache.
[2180] = "Den explizit ausgewählten TBC-Combo-Transport des Spielers beobachten. current verwendet genau GetComboPoints(player,target); maximum verwendet UnitPowerMax(player,powerType) mit dem ursprünglichen Selektor. Andere Familien sind hier nicht verfügbar und müssen ihren vorhandenen Punktressourcen-Beobachter verwenden. Lesbare endliche vorzeichenbehaftete, gebrochene und Nullwerte bleiben erhalten. Fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Daten bleiben nicht verfügbar; eine fehlgeschlagene gewählte Combo-Abfrage fällt nie auf UnitPower zurück. Es wird kein anderer Akteur beobachtet und kein Cache hinzugefügt.",
-- 95b7963d English: Observe the first role result of the exact legacy GetTalentGroupRole(group) dot
--     call on probe- and restricted-policy clients. Forward the readable selected group unchanged,
--     including nil as one argument; do not infer group bounds, substitute another API or query a
--     player unit. The complete legacy primary declaration is not established. Missing, failed,
--     restricted, empty or malformed role data is unavailable; readable nonempty future strings
--     remain exact.
[2181] = "Das erste Rollenergebnis des exakten alten Punktaufrufs GetTalentGroupRole(group) auf Clients mit Probe- oder Restricted-Richtlinie beobachten. Die lesbare ausgewählte Gruppe unverändert weiterreichen, auch nil als ein Argument; keine Gruppengrenzen ableiten, keine andere API einsetzen und keine Spielereinheit abfragen. Die vollständige alte Primärdeklaration ist nicht festgestellt. Fehlende, fehlgeschlagene, eingeschränkte, leere oder fehlerhafte Rollendaten sind nicht verfügbar; lesbare nichtleere künftige Zeichenketten bleiben exakt erhalten.",
-- 79e9c144 English: Observe the first zone PvP classification result with one protected
--     zero-argument dot call. Prefer callable C_PvP.GetZonePVPInfo and use the global helper only
--     when the modern callable is absent. A successful nil or no returned values produces a known
--     empty record; missing, failed, restricted or malformed observations remain unavailable.
--     Readable empty and future strings retain their exact meaning, and unused return fields do not
--     determine availability. Never switch backends after a modern result or failure.
[2182] = "Das erste Ergebnis der PvP-Klassifizierung der Zone mit einem geschützten Punktaufruf ohne Argumente beobachten. Das aufrufbare C_PvP.GetZonePVPInfo bevorzugen und die globale Hilfsfunktion nur verwenden, wenn die moderne fehlt. Ein erfolgreiches nil oder fehlende Rückgabewerte ergeben einen bekannten leeren Datensatz; fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Beobachtungen bleiben nicht verfügbar. Lesbare leere und künftige Zeichenketten behalten ihre exakte Bedeutung, und ungenutzte Rückgabefelder bestimmen nicht die Verfügbarkeit. Nach einem modernen Ergebnis oder Fehlschlag nie das Backend wechseln.",
-- 9570ca02 English: Observe the player current movement speed on supported readable clients. This
--     queries GetUnitSpeed for player only, without testing another unit or redirecting vehicle
--     ownership. Zero means stationary; positive finite fractional speeds remain valid. Missing,
--     failed, restricted or malformed observations return nil with a reason.
[2183] = "Die aktuelle Bewegungsgeschwindigkeit des Spielers auf unterstützten lesbaren Clients beobachten. Dies fragt GetUnitSpeed nur für player ab, ohne eine andere Einheit zu prüfen oder Fahrzeugbesitz umzuleiten. Null bedeutet stillstehend; positive endliche gebrochene Geschwindigkeiten bleiben gültig. Fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Beobachtungen ergeben nil mit einem Grund.",
-- 6b0f7980 English: Observe unit presence on identified client families. Pass the selected unit
--     unchanged to one protected UnitExists call. Preserve readable true and false; missing,
--     failed, restricted, nil or malformed required observations return nil with a reason. No
--     identity, visibility, range or combat-state query is added.
[2184] = "Die Anwesenheit einer Einheit auf identifizierten Client-Familien beobachten. Die ausgewählte Einheit unverändert an einen geschützten Aufruf von UnitExists übergeben. Lesbares true und false bleiben erhalten; fehlende, fehlgeschlagene, eingeschränkte, nil- oder fehlerhafte erforderliche Beobachtungen ergeben nil mit einem Grund. Es wird keine Identitäts-, Sichtbarkeits-, Reichweiten- oder Kampfstatusabfrage hinzugefügt.",
-- a754c7d3 English: Observe whether the player can attack a selected unit that is not dead, using
--     the exact UnitExists, UnitCanAttack and UnitIsDead predicates. Known absence or a readable
--     false attack result returns false without querying death. Required missing, failed,
--     restricted or malformed observations return nil with a reason. This does not test ghosts,
--     range, hostility or ability usability, and does not redirect unit ownership.
[2185] = "Beobachten, ob der Spieler eine ausgewählte, nicht tote Einheit angreifen kann, mit den exakten Prädikaten UnitExists, UnitCanAttack und UnitIsDead. Bekannte Abwesenheit oder ein lesbares false beim Angriff ergibt false, ohne den Tod abzufragen. Erforderliche fehlende, fehlgeschlagene, eingeschränkte oder fehlerhafte Beobachtungen ergeben nil mit einem Grund. Geister, Reichweite, Feindseligkeit und Fähigkeitsnutzbarkeit werden nicht geprüft, und der Einheitenbesitz wird nicht umgeleitet.",
-- d4d5ab66 English: Observed class filename string, false for a known absent unit, or nil when
--     unavailable.
[2186] = "Beobachtete Klassen-Dateinamen-Zeichenkette, false für eine bekannt abwesende Einheit oder nil, wenn nicht verfügbar.",
-- 6b236c0f English: Observed membership, or nil when unavailable.
[2187] = "Beobachtete Zugehörigkeit oder nil, wenn nicht verfügbar.",
-- 7c413887 English: On a selected resource only, target-combo for the explicit TBC player fallback
--     or power for the existing selected-unit transport.
[2188] = "Nur bei einer ausgewählten Ressource: target-combo für den expliziten TBC-Spieler-Rückgriff oder power für den vorhandenen Transport der ausgewählten Einheit.",
-- 4b90146b English: On probe- and restricted-policy clients, observe exact UnitExists(unit), then
--     UnitGUID(unit) only for a present unit. Known absence is false. Present identity requires a
--     readable nonempty GUID; missing, failed, malformed or restricted required facts are
--     unavailable. No health, provider or extra-unit observation is added.
[2189] = "Auf Clients mit Probe- oder Restricted-Richtlinie exakt UnitExists(unit) beobachten, dann UnitGUID(unit) nur für eine vorhandene Einheit. Bekannte Abwesenheit ist false. Eine vorhandene Identität erfordert eine lesbare nichtleere GUID; fehlende, fehlgeschlagene, fehlerhafte oder eingeschränkte erforderliche Fakten sind nicht verfügbar. Es wird keine Beobachtung von Gesundheit, Anbieter oder zusätzlichen Einheiten hinzugefügt.",
-- 7980af82 English: One of class, creature or classification; other metadata kinds are unsupported.
[2190] = "Eines von class, creature oder classification; andere Metadatenarten werden nicht unterstützt.",
-- f4dbfa56 English: One of combat, enemy or pvp; other flag kinds are not supported.
[2191] = "Eines von combat, enemy oder pvp; andere Flag-Arten werden nicht unterstützt.",
-- 6a9d3fdc English: One of stealthed, control or outdoors; no other predicate is invoked.
[2192] = "Eines von stealthed, control oder outdoors; kein anderes Prädikat wird aufgerufen.",
-- e7332ebe English: One rounded numeric result from the original formula.
[2193] = "Ein gerundetes numerisches Ergebnis aus der ursprünglichen Formel.",
-- ffb1aba4 English: Optional collection of key values selecting entries; its own keys are ignored.
[2194] = "Optionale Sammlung von Schlüsselwerten zur Auswahl von Einträgen; ihre eigenen Schlüssel werden ignoriert.",
-- a4bd9302 English: Optional ordering callback called as order(t, leftKey, rightKey).
[2195] = "Optionaler Sortier-Callback, aufgerufen als order(t, leftKey, rightKey).",
