[2872] = "Feinde",
-- 7002c54a English: Number of %s within %s yards
-- %s #1: %s #1: either "enemies" or "allies", e.g. "enemies"
-- %s #2: %s #2: the distance in yards, e.g. 10
[2873] = "Anzahl der %s im Umkreis von %s Metern",
