[3014] = "{item} {{!ist|ist nicht}} in Reichweite{carrying}",
-- 216e438b English: the cooldown on {item} {comparison} {duration}{carrying}
[3015] = "die Abklingzeit von {item} {comparison} {duration}{carrying}",
-- 623bd8c4 English: {unit} {{!is|is not}} in a group
[3016] = "{unit} {{!ist|ist nicht}} in einer Gruppe",
-- fedfc418 English: {unit} {{!is friendly to you|is not friendly to you}}
[3017] = "{unit} {{!ist Ihnen gegenüber freundlich|ist Ihnen gegenüber nicht freundlich}}",
-- 6e21eee4 English: Matches when the selected unit is dead or a ghost. A missing or unreadable unit
--     is unavailable, including under NOT. In a Via Macro announcement, choose Announcement target
--     to follow the supplied unit.
[3018] = "Trifft zu, wenn die gewählte Einheit tot oder ein Geist ist. Eine fehlende oder nicht lesbare Einheit ist nicht verfügbar, auch unter NOT. In einer „Per Makro“-Ankündigung „Ankündigungsziel“ wählen, um der übergebenen Einheit zu folgen.",
-- eaa8232a English: Matches when the game reports the selected unit as friendly to you. This does
--     not imply party or raid membership. A missing or unreadable unit is unavailable.
[3019] = "Trifft zu, wenn das Spiel die gewählte Einheit als Ihnen gegenüber freundlich meldet. Das bedeutet keine Gruppen- oder Schlachtzugsmitgliedschaft. Eine fehlende oder nicht lesbare Einheit ist nicht verfügbar.",
-- b9151b16 English: Assisted Combat {{!is|is not}} suggesting a spell
[3020] = "Der Kampfassistent {{!schlägt einen Zauber vor|schlägt keinen Zauber vor}}",
-- 43bf497e English: Assisted Combat {{!suggests|does not suggest}} %s
-- %s #1: %s #1: a clickable spell link, e.g. "[Fireball]"
[3021] = "Der Kampfassistent {{!schlägt|schlägt nicht}} %s vor",
-- 6c9594a9 English: Matches when Blizzard's Assisted Combat suggests this spell as the next cast.
--     An override counts as its base spell, and the base spell as its override. With no spell
--     chosen, matches whenever Assisted Combat suggests anything.
[3022] = "Trifft zu, wenn Blizzards Kampfassistent diesen Zauber als nächsten Zauber vorschlägt. Eine Überschreibung zählt als ihr Basiszauber und der Basiszauber als seine Überschreibung. Ohne gewählten Zauber trifft es zu, sobald der Kampfassistent irgendetwas vorschlägt.",
-- 44e850ce English: Assisted Combat exists on Retail (and is declared on Forever). Where the game
--     does not offer it, for this character or specialization, or the suggestion cannot be read,
--     this condition is unavailable rather than false, including under NOT.
[3023] = "Den Kampfassistenten gibt es in Retail (unter Forever ist er angekündigt). Wo das Spiel ihn für diesen Charakter oder diese Spezialisierung nicht anbietet oder der Vorschlag nicht gelesen werden kann, ist diese Bedingung nicht verfügbar statt falsch, auch unter NOT.",
-- 32c737f7 English: %s {{!is|is not}} in Blizzard's Assisted Combat rotation
-- %s #1: %s #1: a clickable spell link, e.g. "[Fireball]"
[3024] = "%s {{!ist|ist nicht}} in Blizzards Kampfassistent-Rotation",
-- ae726224 English: Matches when this spell is one Blizzard's Assisted Combat can suggest for your
--     current specialization. Its current override and its base spell count too. Use it to
--     highlight what Assisted Combat leaves out, for example a cooldown that is not in the set.
[3025] = "Trifft zu, wenn dieser Zauber einer ist, den Blizzards Kampfassistent für Ihre aktuelle Spezialisierung vorschlagen kann. Seine aktuelle Überschreibung und sein Basiszauber zählen ebenfalls. Verwenden Sie sie, um hervorzuheben, was der Kampfassistent auslässt, zum Beispiel eine Abklingzeit, die nicht in der Menge enthalten ist.",
-- 2a9b9d24 English: The set is read again whenever your spells change, never guessed. Where the
--     game does not offer Assisted Combat for this character or specialization, or the set cannot
--     be read, this condition is unavailable rather than false, including under NOT.
[3026] = "Die Menge wird bei jeder Änderung Ihrer Zauber neu gelesen, nie geraten. Bietet das Spiel den Kampfassistenten für diesen Charakter oder diese Spezialisierung nicht an oder ist die Menge nicht lesbar, ist diese Bedingung nicht verfügbar statt nicht erfüllt, auch unter NOT.",
-- 10ac60e3 English: Assisted Combat {{!is|is not}} available
[3027] = "Der Kampfassistent {{!ist|ist nicht}} verfügbar",
-- d882c8a9 English: Matches when the game offers Blizzard's Assisted Combat for your character and
--     current specialization. When it does not (for example a specialization Blizzard has no
--     Assisted Combat rotation for, or a client that declares the API but does not offer the
--     feature), this is false, so a branch can fall back to your own steps.
[3028] = "Trifft zu, wenn das Spiel Blizzards Kampfassistenten für Ihren Charakter und Ihre aktuelle Spezialisierung anbietet. Tut es das nicht (zum Beispiel bei einer Spezialisierung, für die Blizzard keine Kampfassistent-Rotation hat, oder bei einem Client, der die API deklariert, aber die Funktion nicht anbietet), ist sie nicht erfüllt, sodass ein Zweig auf Ihre eigenen Schritte zurückfallen kann.",
-- 65331c0d English: Unavailable only where the client has no Assisted Combat API or its answer
--     cannot be read, including under NOT.
[3029] = "Nur nicht verfügbar, wenn der Client keine Kampfassistent-API hat oder seine Antwort nicht lesbar ist, auch unter NOT.",
-- 6f6ccc8f English: rune spell %s
-- Context: Fallback name for a rune with no known spell name; %s is the spell ID (Season of
--     Discovery rune condition).
-- %s #1: %s #1: the spell ID of the rune, e.g. 400000
[3030] = "Runenzauber %s",
-- 7bf70ccc English: rune %s
-- Context: Fallback name for a rune with no known name; %s is the rune ID (Season of Discovery rune
--     condition).
-- %s #1: %s #1: the rune number, e.g. 12
[3031] = "Rune %s",
-- 54791384 English: you {{!have|do not have}} the rune %s engraved
-- %s #1: %s #1: the name of the engraved rune, e.g. "Rune of the Fire"
[3032] = "die Rune %s {{!ist|ist nicht}} eingraviert",
-- e999d0a1 English: <rune>
-- Context: Placeholder in the engraved-rune summary shown until a rune is chosen; keep the angle
--     brackets.
[3033] = "<Rune>",
-- 4e0d82c9 English: Your runes have not loaded yet. Reopen this condition shortly, or enter an ID
--     below.
[3034] = "Ihre Runen sind noch nicht geladen. Öffnen Sie diese Bedingung in Kürze erneut oder geben Sie unten eine ID ein.",
-- 1327b43b English: This character cannot engrave runes. A rune entered by ID below is kept, and is
--     unavailable here.
[3035] = "Dieser Charakter kann keine Runen eingravieren. Eine unten per ID eingegebene Rune bleibt erhalten und ist hier nicht verfügbar.",
-- 7294ffa8 English: Slot %d
-- Context: Fallback name for an equipment slot group in the rune condition's slot dropdown; %d is
--     the slot number.
-- %d #1: %d #1: the equipment slot category number, e.g. 5
[3036] = "Platz %d",
-- 1eccb682 English: Equipment Slot
-- Context: Label of the dropdown in the rune condition: the equipment slot (chest, hands, legs ...)
--     the rune is engraved on.
[3037] = "Ausrüstungsplatz",
-- f55862c6 English: Rune
-- Context: Label of the dropdown in the rune condition: which rune. Also a help heading.
[3038] = "Rune",
-- 577a2fa4 English: Rune Spell ID
-- Context: Label of the edit box in the rune condition: the ID of a spell the rune teaches. Also
--     part of a help heading.
[3039] = "Runenzauber-ID",
-- b84ca6e3 English: Rune ID
-- Context: Label of the edit box in the rune condition: the rune's own numeric ID, for runes that
--     teach no spell. Also part of a help heading.
[3040] = "Runen-ID",
-- a698651e English: Matches when a Season of Discovery rune is engraved on one of your equipped
--     items. Passive runes count too, which a known-spell test cannot see.
[3041] = "Trifft zu, wenn eine Rune aus Season of Discovery in einen Ihrer angelegten Gegenstände eingraviert ist. Passive Runen zählen ebenfalls, was ein Test auf bekannte Zauber nicht sehen kann.",
-- 1daa202b English: Pick one of your known runes by equipment slot. The rune is saved by the first
--     spell it teaches, so a shared rotation names it on any character.
[3042] = "Wählen Sie eine Ihrer bekannten Runen nach Ausrüstungsplatz. Die Rune wird über den ersten Zauber gespeichert, den sie lehrt, daher benennt eine geteilte Rotation sie auf jedem Charakter.",
-- 8151a8cf English: Enter a spell the rune teaches, or the rune's own ID (its skill line ability
--     ID) for a rune that teaches no spell. Entering one clears the other.
[3043] = "Geben Sie einen Zauber ein, den die Rune lehrt, oder die eigene ID der Rune (ihre Fertigkeitslinien-Fähigkeits-ID) für eine Rune, die keinen Zauber lehrt. Die Eingabe des einen löscht den anderen.",
-- 868afb4d English: Engraving exists only on Season of Discovery realms. Elsewhere, and until your
--     runes have loaded after logging in, this condition is unavailable rather than false,
--     including under NOT. The Phase 7 shoulder runes are not engravings and are not seen. This is
--     not the Death Knight Rune condition.
[3044] = "Gravuren gibt es nur auf Realms von Season of Discovery. Anderswo und bis Ihre Runen nach der Anmeldung geladen sind, ist diese Bedingung nicht verfügbar statt nicht erfüllt, auch unter NOT. Die Schulterrunen aus Phase 7 sind keine Gravuren und werden nicht erkannt. Dies ist nicht die Bedingung Rune der Todesritter.",
-- 2cfaca8e English: Your talents cannot be listed right now (%s). A node ID entered below is kept
--     and evaluated.
-- %s #1: %s #1: why the talents cannot be listed, a short code (shown as-is), e.g. "not-ready"
[3045] = "Deine Talente können gerade nicht aufgelistet werden (%s). Eine unten eingegebene Knoten-ID bleibt erhalten und wird ausgewertet.",
-- 0d2b4c68 English: Talents can be listed only for your own class. A node ID entered below is kept
--     and evaluated.
[3046] = "Talente lassen sich nur für deine eigene Klasse auflisten. Eine unten eingegebene Knoten-ID bleibt erhalten und wird ausgewertet.",
-- 7417e36a English: Class talents
-- Context: Group heading in the talent dropdown: talents shared by all specializations of the
--     class.
[3047] = "Klassentalente",
-- 9900921e English: Specialization talents
-- Context: Group heading in the talent dropdown: talents of the chosen specialization only.
[3048] = "Talente der Spezialisierung",
-- 6eaab468 English: Class and specialization talents
[3049] = "Klassen- und Spezialisierungstalente",
-- 7d26d446 English: Hero talents: %s
-- %s #1: %s #1: the name of the hero talent tree, e.g. "Herald of the Sun"
[3050] = "Heldentalente: %s",
-- cb9e8664 English: Tier
-- Context: Label of the dropdown in the Classic grid talent condition: which row (tier) of talents.
[3051] = "Stufe",
