[3158] = "Instanz-ID %s",
-- 08c231ad English: you {{!are|are not}} in an instance (%s)
-- %s #1: %s #1: the instance details separated by commas, e.g. "type Raid, difficulty Heroic, ID 409"
[3159] = "Sie {{!befinden sich|befinden sich nicht}} in einer Instanz (%s)",
-- 364397ab English: Any difficulty
-- Context: Option at the top of the instance difficulty dropdown: do not restrict by difficulty.
[3160] = "Beliebige Schwierigkeit",
-- bd945e03 English: None (use the item above)
[3161] = "Keiner (Gegenstand oben verwenden)",
-- 02de34c4 English: A number of players, or a percent of the whole group when the box is ticked.
--     You are always part of the group and of every count you fit.
[3162] = "Eine Anzahl von Spielern oder, wenn das Kästchen angekreuzt ist, ein Prozentsatz der gesamten Gruppe. Sie gehören immer zur Gruppe und zu jeder Zählung, auf die Sie zutreffen.",
-- d758a0ce English: Matches while you are in the chosen state. Mounted, swimming (at the surface or
--     under water), flying, falling and in a rested area (an inn or a capital city) describe where
--     you are and how you move. Dead means you have died and not yet released your spirit; Ghost
--     means you have released it. A state the game cannot report right now is unavailable rather
--     than false. Being stealthed, outdoors or in control of your character have their own
--     conditions, and Is Dead or Ghost tests any unit.
[3163] = "Trifft zu, solange Sie sich im gewählten Zustand befinden. Aufgesessen, Schwimmen (an der Oberfläche oder unter Wasser), Fliegen, Fallen und In einem Erholungsgebiet (ein Gasthaus oder eine Hauptstadt) beschreiben, wo Sie sind und wie Sie sich bewegen. Tot bedeutet, dass Sie gestorben sind und Ihren Geist noch nicht freigelassen haben; Geist bedeutet, dass Sie ihn freigelassen haben. Ein Zustand, den das Spiel gerade nicht melden kann, ist nicht verfügbar statt falsch. Getarnt sein, im Freien sein und die Kontrolle über Ihren Charakter haben besitzen eigene Bedingungen, und „Ist tot oder Geist“ prüft jede beliebige Einheit.",
-- b4a1a7b5 English: Counts the players in your party or raid, always including you: the whole
--     group, the members holding an assigned role (Tank, Healer or damage dealer) or the members
--     who are dead or ghosts. Tick the box to compare a percent of the whole group instead of a
--     number of players, for example more than 50 percent dead. Alone, the group is 1 player. A
--     member with no assigned role is not counted under any role. A member the game cannot report
--     makes the count unavailable rather than too low.
[3164] = "Zählt die Spieler Ihrer Gruppe oder Ihres Schlachtzugs, immer einschließlich Ihrer selbst: die ganze Gruppe, die Mitglieder mit einer zugewiesenen Rolle (Tank, Heiler oder Schadensverursacher) oder die Mitglieder, die tot oder Geister sind. Kreuzen Sie das Kästchen an, um statt einer Spielerzahl einen Prozentsatz der gesamten Gruppe zu vergleichen, zum Beispiel mehr als 50 Prozent tot. Allein besteht die Gruppe aus 1 Spieler. Ein Mitglied ohne zugewiesene Rolle wird unter keiner Rolle gezählt. Ein Mitglied, das das Spiel nicht melden kann, macht die Zählung nicht verfügbar, statt sie zu niedrig auszugeben.",
-- e1167554 English: Balance Druid Eclipse. Choose the measure first. Direction matches while the
--     Eclipse bar is heading toward a Solar or a Lunar Eclipse. Energy compares the bar itself,
--     from -100 (a full Lunar Eclipse) to 100 (a full Solar Eclipse), using the operator and value.
--     Only the fields of the chosen measure are used.
[3165] = "Eklipse des Gleichgewichts-Druiden. Wählen Sie zuerst den Messwert. „Richtung“ trifft zu, solange sich die Eklipseleiste auf eine Sonnen- oder Mondfinsternis zubewegt. „Energie“ vergleicht die Leiste selbst, von -100 (volle Mondfinsternis) bis 100 (volle Sonnenfinsternis), mit Operator und Wert. Es werden nur die Felder des gewählten Messwerts verwendet.",
-- 66261852 English: Instance Difficulty and Instance ID are optional. Every part you set must
--     match, for example a Dungeon on Heroic difficulty, or one particular instance by its ID (the
--     editor shows the ID of the instance you are in). The ID does not change with the game's
--     language the way a zone name does.
[3166] = "Instanzschwierigkeit und Instanz-ID sind optional. Jeder festgelegte Teil muss zutreffen, zum Beispiel ein Dungeon im Schwierigkeitsgrad Heroisch oder eine bestimmte Instanz anhand ihrer ID (der Editor zeigt die ID der Instanz an, in der Sie sich befinden). Die ID ändert sich nicht mit der Spielsprache wie ein Zonenname.",
-- 347c420f English: Choose a trinket slot to read whatever is equipped there, so one rotation works
--     for every trinket; the item above is then ignored. An empty slot is false, and a trinket with
--     no on-use effect is unavailable.
[3167] = "Wählen Sie einen Schmuckstückplatz, um zu lesen, was dort angelegt ist, damit eine Rotation für jedes Schmuckstück funktioniert; der Gegenstand oben wird dann ignoriert. Ein leerer Platz ist falsch, und ein Schmuckstück ohne Benutzungseffekt ist nicht verfügbar.",
-- 41e5c95c English: Measure your Auto Shot or wand shot instead of a melee weapon. Choose Off Hand
--     or Ranged, not both. The time remaining needs the combat log, so it works on Classic Era,
--     Burning Crusade and Mists of Pandaria but not on Retail or Forever.
[3168] = "Misst Ihren Automatischen Schuss oder Zauberstabschuss statt einer Nahkampfwaffe. Wählen Sie Schildhand oder Fernkampf, nicht beides. Die verbleibende Zeit benötigt das Kampflog und funktioniert daher in Classic Era, Burning Crusade und Mists of Pandaria, aber nicht in Retail oder Forever.",
-- a8b3d1b8 English: Number of %s in combat within %s yards
-- %s #1: %s #1: either "enemies" or "allies", e.g. "enemies"
-- %s #2: %s #2: the distance in yards, e.g. 10
[3169] = "Anzahl der %s im Kampf im Umkreis von %s Metern",
-- e7ccbb83 English: Count only units that are in combat. For enemies that is the ones fighting
--     right now, not every enemy whose nameplate is visible. A unit whose combat state the game
--     will not report makes the count unavailable.
[3170] = "Zählt nur Einheiten, die im Kampf sind. Bei Feinden sind das die, die gerade kämpfen, nicht jeder Feind mit sichtbarer Namensplakette. Eine Einheit, deren Kampfstatus das Spiel nicht meldet, macht die Anzahl nicht verfügbar.",
-- ae7064c5 English: CPU capture complete. Use General > CPU report or /rm perf cpu report to view
--     and copy it.
[3171] = "CPU-Erfassung abgeschlossen. Unter Allgemein > CPU-Bericht oder mit /rm perf cpu report lässt sie sich ansehen und kopieren.",
-- be403677 English: Runtime capture complete. Use General > Runtime report or /rm perf runtime
--     report to view and copy it.
[3172] = "Laufzeiterfassung abgeschlossen. Unter Allgemein > Laufzeitbericht oder mit /rm perf runtime report lässt sie sich ansehen und kopieren.",
-- e7cb84d8 English: Memory capture complete. Use General > Memory report or /rm perf memory report
--     to view and copy it.
[3173] = "Speichererfassung abgeschlossen. Unter Allgemein > Speicherbericht oder mit /rm perf memory report lässt sie sich ansehen und kopieren.",
-- df7dc1a7 English: Usage: /rm perf cpu||runtime||memory [seconds||start||stop||report], or /rm
--     perf probe
[3174] = "Verwendung: /rm perf cpu||runtime||memory [seconds||start||stop||report] oder /rm perf probe",
-- e4d45a37 English: Capture stopped. Use /rm perf %s report to view and copy it.
-- %s #1: %s #1: the capture kind used in the command, "cpu", "runtime" or "memory" (shown as-is), e.g. "cpu"
[3175] = "Erfassung gestoppt. Mit /rm perf %s report lässt sie sich ansehen und kopieren.",
-- 6f8012ee English: Capture started for %g seconds. Close configuration, then use /rm perf %s
--     report.
-- %g #1: %g #1: the capture length in seconds, e.g. 10
-- %s #2: %s #2: the capture kind used in the command, "cpu", "runtime" or "memory" (shown as-is), e.g. "cpu"
[3176] = "Erfassung für %g Sekunden gestartet. Konfiguration schließen, dann /rm perf %s report verwenden.",
-- e8370df2 English: Choose a duration from 1 to %d seconds.
-- %d #1: %d #1: the longest allowed capture length in seconds, e.g. 60
[3177] = "Eine Dauer von 1 bis %d Sekunden wählen.",
-- 01fdff8c English: Usage: /rm perf engine [lean||standard]
[3178] = "Verwendung: /rm perf engine [lean||standard]",
-- e670bdea English: Evaluation engine: %s
