-- %s #1: the name of the macro that was created, e.g. "RM skull/tgt"
[3409] = "Ziehen Sie das Makro %s auf einen Platz der Aktionsleiste.",
-- 45a37997 English: Empty your cursor before binding.
[3410] = "Leeren Sie vor dem Binden Ihren Mauszeiger.",
-- 69f3d263 English: Your character macros are full, so the macro could not be made.
