[3414] = "Empfiehlt, ein Makro zu drücken, das die Schlachtzugsmarkierung setzt",
-- 2dacd008 English: uses a Set Mark step this client cannot run
[3415] = "verwendet einen Schritt „Markierung setzen“, den dieser Client nicht ausführen kann",
